static const struct nh_quest_descriptor nh_quest_descriptors[] = {
    {"Arc", "assignquest", "synopsis", "nethack.quest.arc.assignquest.synopsis", "[%nC has stolen %o.  Locate %i, defeat %ni, and return %O.]", 0, nh_quest_bindings_0, 6},
    {"Arc", "assignquest", "text", "nethack.quest.arc.assignquest.text", "\"Grave times have befallen the college, for %na has\nstolen %o.  Without it, the board of directors of\nthe university will soon have no choice but to revoke our research grants.\n\n\"You must locate the entrance to %i.  Within it,\nyou will find %n.\n\n\"You must then defeat %n and return %o\nto me.\n\n\"Only in this way will we be able to prevent the budget cuts that could\nclose this college.\n\n\"May the wisdom of %d be your guide.\"", 0, nh_quest_bindings_1, 5},
    {"Arc", "badalign", "synopsis", "nethack.quest.arc.badalign.synopsis", "[\"%pC, you have strayed from the %a path.  Purify yourself!\"]", 0, nh_quest_bindings_2, 3},
    {"Arc", "badalign", "text", "nethack.quest.arc.badalign.text", "\"%pC!  I've heard that you've been using sloppy techniques.  Your\nresults lately can hardly be called suitable for %ra!\n\n\"How could you have strayed from the %a path?  Go from here, and come\nback only when you have purified yourself.\"", 0, nh_quest_bindings_3, 5},
    {"Arc", "badlevel", "synopsis", "nethack.quest.arc.badlevel.synopsis", "[%pC, a mere %r is too inexperienced.]", 0, nh_quest_bindings_4, 3},
    {"Arc", "badlevel", "text", "nethack.quest.arc.badlevel.text", "\"%p, you are yet too inexperienced to undertake such a demanding\nquest.  A mere %r could not possibly face the rigors demanded and\nsurvive.  Go forth, and come here again when your adventures have further\ntaught you.\"", 0, nh_quest_bindings_5, 2},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_1", "\"Try your best, %p.  You cannot defeat me.\"", 1, nh_quest_bindings_6, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_10", "\"Die %c!  I shall exhibit your carcass as a trophy.\"", 10, nh_quest_bindings_7, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_2", "\"I shall rend the flesh from your body whilst you still breathe!\"", 2, NULL, 0},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_3", "\"First you, %p, then I shall destroy your mentor, %l.\"", 3, nh_quest_bindings_9, 2},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_4", "\"Tiring yet, %p?  I draw my power from my master and cannot falter!\"", 4, nh_quest_bindings_10, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_5", "\"I shall rend thy soul from thy body and consume it!\"", 5, NULL, 0},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_6", "\"You are far too %a -- it weakens you.  You shall die in this place.\"", 6, nh_quest_bindings_12, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_7", "\"%d has forsaken you!  You are lost now!\"", 7, nh_quest_bindings_13, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_8", "\"A mere %r cannot hope to defeat me!\"", 8, nh_quest_bindings_14, 1},
    {"Arc", "discourage", "item", "nethack.quest.arc.discourage.item_9", "\"If you are the best %l can send, I have nothing to fear.\"", 9, nh_quest_bindings_15, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_1", "\"Beware, for %n is powerful and cunning.\"", 1, nh_quest_bindings_16, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_10", "\"You may be able to sense %o when you are near.\"", 10, nh_quest_bindings_17, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_2", "\"To locate the entrance to %i, you must pass many traps.\"", 2, nh_quest_bindings_18, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_3", "\"A %nt may be vulnerable to attacks by magical cold.\"", 3, nh_quest_bindings_19, 2},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_4", "\"Call upon %d when you encounter %n.\"", 4, nh_quest_bindings_20, 2},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_5", "\"You must destroy %n.  It will pursue you otherwise.\"", 5, nh_quest_bindings_21, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_6", "\"%oC is a mighty talisman.  With it you can destroy %n.\"", 6, nh_quest_bindings_22, 3},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_7", "\"Go forth with the blessings of %d.\"", 7, nh_quest_bindings_23, 1},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_8", "\"I will have my %gP watch for your return.\"", 8, nh_quest_bindings_24, 2},
    {"Arc", "encourage", "item", "nethack.quest.arc.encourage.item_9", "\"Remember not to stray from the true %a path.\"", 9, nh_quest_bindings_25, 1},
    {"Arc", "firsttime", "synopsis", "nethack.quest.arc.firsttime.synopsis", "[You arrive at %H, but all is not well.]", 0, nh_quest_bindings_26, 1},
    {"Arc", "firsttime", "text", "nethack.quest.arc.firsttime.text", "You are suddenly in familiar surroundings.  The buildings in the distance\nseem to be those of your old alma mater, but something is wrong.  It feels\nas if there has been a riot recently, or %H has\nbeen under siege.\n\nAll of the windows are boarded up, and there are objects scattered around\nthe entrance.\n\nStrange forbidding shapes seem to be moving in the distance.", 0, nh_quest_bindings_27, 1},
    {"Arc", "goal_alt", "text", "nethack.quest.arc.goal_alt.text", "You have returned to %ns lair.", 0, nh_quest_bindings_28, 1},
    {"Arc", "goal_first", "synopsis", "nethack.quest.arc.goal_first.synopsis", "[This strange feeling must be the presence of %o.]", 0, nh_quest_bindings_29, 1},
    {"Arc", "goal_first", "text", "nethack.quest.arc.goal_first.text", "A strange feeling washes over you, and you think back to things you\nlearned during the many lectures of %l.\n\nYou realize the feeling must be the presence of %o.", 0, nh_quest_bindings_30, 2},
    {"Arc", "goal_next", "text", "nethack.quest.arc.goal_next.text", "The familiar presence of %o is in the ether.", 0, nh_quest_bindings_31, 1},
    {"Arc", "gotit", "synopsis", "nethack.quest.arc.gotit.synopsis", "[The power of %o flows through your body!  You must return it to %l.]", 0, nh_quest_bindings_32, 2},
    {"Arc", "gotit", "text", "nethack.quest.arc.gotit.text", "The power of %o flows through your body!  You feel\nas if you could now take on the Wizard of Yendor himself and win, but\nyou know you must return %o to %l.", 0, nh_quest_bindings_33, 2},
    {"Arc", "guardtalk_after", "item", "nethack.quest.arc.guardtalk_after.item_1", "\"Did you see Lash LaRue in 'Song of Old Wyoming' the other night?\"", 1, NULL, 0},
    {"Arc", "guardtalk_after", "item", "nethack.quest.arc.guardtalk_after.item_2", "\"Hey man, got any potions of hallucination for sale?\"", 2, NULL, 0},
    {"Arc", "guardtalk_after", "item", "nethack.quest.arc.guardtalk_after.item_3", "\"I guess you are guaranteed to make full professor now.\"", 3, NULL, 0},
    {"Arc", "guardtalk_after", "item", "nethack.quest.arc.guardtalk_after.item_4", "\"So, what was worse, %n or your entrance exams?\"", 4, nh_quest_bindings_37, 1},
    {"Arc", "guardtalk_after", "item", "nethack.quest.arc.guardtalk_after.item_5", "\"%oC is impressive, but nothing like the bones I dug up!\"", 5, nh_quest_bindings_38, 1},
    {"Arc", "guardtalk_before", "item", "nethack.quest.arc.guardtalk_before.item_1", "\"Did you see Lash LaRue in 'Song of Old Wyoming' the other night?\"", 1, NULL, 0},
    {"Arc", "guardtalk_before", "item", "nethack.quest.arc.guardtalk_before.item_2", "\"Hey man, got any potions of hallucination for sale?\"", 2, NULL, 0},
    {"Arc", "guardtalk_before", "item", "nethack.quest.arc.guardtalk_before.item_3", "\"Did you see the artifact %l brought back from the last dig?\"", 3, nh_quest_bindings_41, 1},
    {"Arc", "guardtalk_before", "item", "nethack.quest.arc.guardtalk_before.item_4", "\"So what species do *you* think we evolved from?\"", 4, NULL, 0},
    {"Arc", "guardtalk_before", "item", "nethack.quest.arc.guardtalk_before.item_5", "\"So you're %ls prize pupil!  I don't know what he sees in you.\"", 5, nh_quest_bindings_43, 2},
    {"Arc", "hasamulet", "synopsis", "nethack.quest.arc.hasamulet.synopsis", "[Take the Amulet to the Astral Plane and sacrifice it at the altar of %d.]", 0, nh_quest_bindings_44, 1},
    {"Arc", "hasamulet", "text", "nethack.quest.arc.hasamulet.text", "\"Congratulations, %p.  I wondered if anyone could prevail against\nthe Wizard and the minions of Moloch.  Now, you must embark on one\nfinal adventure.\n\n\"Take the Amulet, and find your way onto the Astral Plane.\nThere you must find the altar of %d and sacrifice the\nAmulet on that altar to fulfill your destiny.\n\n\"Remember, your path now should always be upwards.\"", 0, nh_quest_bindings_45, 2},
    {"Arc", "killed_nemesis", "text", "nethack.quest.arc.killed_nemesis.text", "The body of %n dissipates in a cloud of noxious fumes.", 0, nh_quest_bindings_46, 1},
    {"Arc", "leader_first", "synopsis", "nethack.quest.arc.leader_first.synopsis", "[\"You have returned, %p, to a difficult task.\"]", 0, nh_quest_bindings_47, 1},
    {"Arc", "leader_first", "text", "nethack.quest.arc.leader_first.text", "\"Finally you have returned, %p.  You were always\nmy most promising student.  Allow me to see if you are ready for the\nmost difficult task of your career.\"", 0, nh_quest_bindings_48, 1},
    {"Arc", "leader_last", "synopsis", "nethack.quest.arc.leader_last.synopsis", "[\"%pC, you have failed us.  Begone!\"]", 0, nh_quest_bindings_49, 2},
    {"Arc", "leader_last", "text", "nethack.quest.arc.leader_last.text", "\"%p, you have failed us.  All of my careful training has been in\nvain.  Begone!  Your tenure at this college has been revoked!\n\n\"You are a disgrace to the profession!\"", 0, nh_quest_bindings_50, 1},
    {"Arc", "leader_next", "text", "nethack.quest.arc.leader_next.text", "\"Again, %p, you stand before me.\nLet me see if you have gained experience in the interim.\"", 0, nh_quest_bindings_51, 1},
    {"Arc", "leader_other", "text", "nethack.quest.arc.leader_other.text", "\"Once more, %p, you have returned from the field.\nAre you finally ready for the task that must be accomplished?\"", 0, nh_quest_bindings_52, 1},
    {"Arc", "locate_first", "synopsis", "nethack.quest.arc.locate_first.synopsis", "[This foreboding edifice must hide the entrance to %i.]", 0, nh_quest_bindings_53, 1},
    {"Arc", "locate_first", "text", "nethack.quest.arc.locate_first.text", "A plain opens before you.  Beyond the plain lies a foreboding edifice.\n\nYou have the feeling that you will soon find the entrance to\n%i.", 0, nh_quest_bindings_54, 1},
    {"Arc", "locate_next", "text", "nethack.quest.arc.locate_next.text", "Once again, you are near the entrance to %i.", 0, nh_quest_bindings_55, 1},
    {"Arc", "nemesis_first", "synopsis", "nethack.quest.arc.nemesis_first.synopsis", "[\"Come, %p, I shall destroy you!\"]", 0, nh_quest_bindings_56, 1},
    {"Arc", "nemesis_first", "text", "nethack.quest.arc.nemesis_first.text", "\"So, %p, you think that you can succeed in recovering\n%o, when your teacher, %l, has already failed.\n\n\"Come, try your best!  I shall destroy you, and gnaw on your bones.\"", 0, nh_quest_bindings_57, 3},
    {"Arc", "nemesis_next", "synopsis", "nethack.quest.arc.nemesis_next.synopsis", "[\"Again you try to best me, %p?  You shall never recover %o.\"]", 0, nh_quest_bindings_58, 2},
    {"Arc", "nemesis_next", "text", "nethack.quest.arc.nemesis_next.text", "\"Again you try to best me, eh %p?  Well, you shall fail again.\n\n\"You shall never recover %o.\n\n\"I shall bear your soul to the Plane of Origins for my master's pleasure.\"", 0, nh_quest_bindings_59, 2},
    {"Arc", "nemesis_other", "text", "nethack.quest.arc.nemesis_other.text", "\"You persist yet %p!  Good.  Now, you shall die!\"", 0, nh_quest_bindings_60, 1},
    {"Arc", "nemesis_wantsit", "text", "nethack.quest.arc.nemesis_wantsit.text", "\"I shall have %o from you, %p, then feast\nupon your entrails!\"", 0, nh_quest_bindings_61, 2},
    {"Arc", "nexttime", "text", "nethack.quest.arc.nexttime.text", "Once again, you are back at %H.", 0, nh_quest_bindings_62, 1},
    {"Arc", "offeredit", "synopsis", "nethack.quest.arc.offeredit.synopsis", "[%lC instructs you to guard %o from now on.]", 0, nh_quest_bindings_63, 3},
    {"Arc", "offeredit", "text", "nethack.quest.arc.offeredit.text", "%lC touches %o briefly, gazes into it,\nthen smiles at you and says:\n\n\"Well done, %p.  You have defeated %n and\nrecovered %o.  But I fear that it shall never be safe\nhere.\n\nPlease take %o with you.  You, %p, can\nguard it now far better than I.\n\nMay the blessings of %d follow you and guard you.\"", 0, nh_quest_bindings_64, 6},
    {"Arc", "offeredit2", "synopsis", "nethack.quest.arc.offeredit2.synopsis", "[\"Resume your search for the Amulet beyond the magic portal to %Z.\"]", 0, nh_quest_bindings_65, 1},
    {"Arc", "offeredit2", "text", "nethack.quest.arc.offeredit2.text", "\"Careful, %p!  %oC might break, and that would be\na tragic loss.  You are its keeper now, and the time has come to\nresume your search for the Amulet.  %Z await your\nreturn through the magic portal that brought you here.\"", 0, nh_quest_bindings_66, 4},
    {"Arc", "othertime", "text", "nethack.quest.arc.othertime.text", "You are back at %H.\nYou have an odd feeling this may be the last time you ever come here.", 0, nh_quest_bindings_67, 1},
    {"Arc", "posthanks", "synopsis", "nethack.quest.arc.posthanks.synopsis", "[\"Have you progressed with your quest to regain the Amulet of Yendor for %d?\"]", 0, nh_quest_bindings_68, 1},
    {"Arc", "posthanks", "text", "nethack.quest.arc.posthanks.text", "\"Welcome back, %p.  Have you progressed with your quest to\nregain the Amulet of Yendor for %d?\"", 0, nh_quest_bindings_69, 2},
    {"Bar", "assignquest", "synopsis", "nethack.quest.bar.assignquest.synopsis", "[\"Find %n, defeat %ni, and return %o to us.\"]", 0, nh_quest_bindings_70, 3},
    {"Bar", "assignquest", "text", "nethack.quest.bar.assignquest.text", "\"The world is in great need of your assistance, %p.\n\n\"About six months ago, I learned that a mysterious sorcerer, known\nas %n, had begun to gather a large group of cutthroats and brigands\nabout %ni.\n\n\"At about the same time, these people you once rode with `liberated' a\npotent magical talisman, %o, from a Turanian caravan.\n\n\"%nC and %nj Black Horde swept down upon %i and defeated\nthe people there, driving them out into the desert.  He has taken\n%o, and seeks to bend it to %nj will.  I detected the\nsubtle changes in the currents of fate, and joined these people.\nThen I sent forth a summons for you.\n\n\"If %n can bend %o to %nj will, he will become\nalmost indestructible.  He will then be able to enslave the minds of\nmen across the world.  You are the only hope.  The gods smile upon you,\nand with %d behind you, you alone can defeat %n.\n\n\"You must go to %i.  From there, you can track down\n%n, defeat %ni, and return %o to us.  Only\nthen will the world be safe.\"", 0, nh_quest_bindings_71, 8},
    {"Bar", "badalign", "synopsis", "nethack.quest.bar.badalign.synopsis", "[\"You have wandered from the path of the %a.  Come back when you have atoned.\"]", 0, nh_quest_bindings_72, 1},
    {"Bar", "badalign", "text", "nethack.quest.bar.badalign.text", "\"%pC!  You have wandered from the path of the %a!\nIf you attempt to overcome %n in this state, he will surely\nenslave your soul.  Your only hope, and ours, lies in your purification.\nGo forth, and return when you feel ready.\"", 0, nh_quest_bindings_73, 4},
    {"Bar", "badlevel", "synopsis", "nethack.quest.bar.badlevel.synopsis", "[\"You are too inexperienced.  Come back when you are %Ra.\"]", 0, nh_quest_bindings_74, 2},
    {"Bar", "badlevel", "text", "nethack.quest.bar.badlevel.text", "\"%p, I fear that you are as yet too inexperienced to face\n%n.  Only %Ra with the help of %d could ever hope to\ndefeat %ni.\"", 0, nh_quest_bindings_75, 6},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_1", "\"My pets will dine on your carcass tonight!\"", 1, NULL, 0},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_10", "\"You have failed, %c.  Now, my victory is complete.\"", 10, nh_quest_bindings_77, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_2", "\"You are a sorry excuse for %ra.\"", 2, nh_quest_bindings_78, 2},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_3", "\"Run while you can, %c.  My next spell will be your last.\"", 3, nh_quest_bindings_79, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_4", "\"I shall use your very skin to bind my next grimoire.\"", 4, NULL, 0},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_5", "\"%d cannot protect you now.  Here, you die.\"", 5, nh_quest_bindings_81, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_6", "\"Your %a nature makes you weak.  You cannot defeat me.\"", 6, nh_quest_bindings_82, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_7", "\"Come, %c.  I shall kill you, then unleash the horde on your tribe.\"", 7, nh_quest_bindings_83, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_8", "\"Once you are dead, my horde shall finish off %l, and your tribe.\"", 8, nh_quest_bindings_84, 1},
    {"Bar", "discourage", "item", "nethack.quest.bar.discourage.item_9", "\"Fight, %c, or are you afraid of the mighty %n?\"", 9, nh_quest_bindings_85, 2},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_1", "\"%nC is strong in the dark arts, but not immune to cold steel.\"", 1, nh_quest_bindings_86, 2},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_10", "\"You have a great road to travel, %p, but only after you defeat %n.\"", 10, nh_quest_bindings_87, 2},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_2", "\"Remember that %n is a great sorcerer.  He lived in the time of Atlantis.\"", 2, nh_quest_bindings_88, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_3", "\"If you fail, %p, I will not be able to protect these people long.\"", 3, nh_quest_bindings_89, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_4", "\"To enter %i, you must be very stealthy.  The horde will be on guard.\"", 4, nh_quest_bindings_90, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_5", "\"Call upon %d in your time of need.\"", 5, nh_quest_bindings_91, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_6", "\"May %d protect you, and guide your steps.\"", 6, nh_quest_bindings_92, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_7", "\"If you can lay hands upon %o, carry it for good fortune.\"", 7, nh_quest_bindings_93, 1},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_8", "\"I cannot stand against %ns sorcery.  But %d will help you.\"", 8, nh_quest_bindings_94, 3},
    {"Bar", "encourage", "item", "nethack.quest.bar.encourage.item_9", "\"Do not fear %n.  I know you can defeat %ni.\"", 9, nh_quest_bindings_95, 2},
    {"Bar", "firsttime", "synopsis", "nethack.quest.bar.firsttime.synopsis", "[You reach the vicinity of %H, but sense evil magic nearby.]", 0, nh_quest_bindings_96, 1},
    {"Bar", "firsttime", "text", "nethack.quest.bar.firsttime.text", "Warily you scan your surroundings, all of your senses alert for signs\nof possible danger.  Off in the distance, you can %x the familiar shapes\nof %H.\n\nBut why, you think, should %l be there?\n\nSuddenly, the hairs on your neck stand on end as you detect the aura of\nevil magic in the air.\n\nWithout thought, you ready your weapon, and mutter under your breath:\n\n    \"By %d, there will be blood spilt today.\"", 0, nh_quest_bindings_97, 4},
    {"Bar", "goal_first", "synopsis", "nethack.quest.bar.goal_first.synopsis", "[This is surely the lair of %n.]", 0, nh_quest_bindings_98, 1},
    {"Bar", "goal_first", "text", "nethack.quest.bar.goal_first.text", "The hairs on the nape of your neck lift as you sense an energy in the\nvery air around you.  You fight down a primordial panic that seeks to\nmake you turn and run.  This is surely the lair of %n.", 0, nh_quest_bindings_99, 1},
    {"Bar", "goal_next", "text", "nethack.quest.bar.goal_next.text", "Yet again you feel the air around you heavy with malevolent magical energy.", 0, NULL, 0},
    {"Bar", "gotit", "synopsis", "nethack.quest.bar.gotit.synopsis", "[You feel the power of %o flowing through your hands.]", 0, nh_quest_bindings_101, 1},
    {"Bar", "gotit", "text", "nethack.quest.bar.gotit.text", "As you pick up %o, you feel the power of it\nflowing through your hands.  It seems to be in two or more places\nat once, even though you are holding it.", 0, nh_quest_bindings_102, 1},
    {"Bar", "guardtalk_after", "item", "nethack.quest.bar.guardtalk_after.item_1", "\"The battles here have been good -- our enemies' blood soaks the soil!\"", 1, NULL, 0},
    {"Bar", "guardtalk_after", "item", "nethack.quest.bar.guardtalk_after.item_2", "\"Remember that glory is crushing your enemies beneath your feet!\"", 2, NULL, 0},
    {"Bar", "guardtalk_after", "item", "nethack.quest.bar.guardtalk_after.item_3", "\"Times will be good again, now that the horde is vanquished.\"", 3, NULL, 0},
    {"Bar", "guardtalk_after", "item", "nethack.quest.bar.guardtalk_after.item_4", "\"You have brought our clan much honor in defeating %n.\"", 4, nh_quest_bindings_106, 1},
    {"Bar", "guardtalk_after", "item", "nethack.quest.bar.guardtalk_after.item_5", "\"You will be a worthy successor to %l.\"", 5, nh_quest_bindings_107, 1},
    {"Bar", "guardtalk_before", "item", "nethack.quest.bar.guardtalk_before.item_1", "\"The battles here have been good -- our enemies' blood soaks the soil!\"", 1, NULL, 0},
    {"Bar", "guardtalk_before", "item", "nethack.quest.bar.guardtalk_before.item_2", "\"Remember that glory is crushing your enemies beneath your feet!\"", 2, NULL, 0},
    {"Bar", "guardtalk_before", "item", "nethack.quest.bar.guardtalk_before.item_3", "\"There has been little treasure to loot, since the horde arrived.\"", 3, NULL, 0},
    {"Bar", "guardtalk_before", "item", "nethack.quest.bar.guardtalk_before.item_4", "\"The horde is mighty in numbers, but they have little courage.\"", 4, NULL, 0},
    {"Bar", "guardtalk_before", "item", "nethack.quest.bar.guardtalk_before.item_5", "\"%lC is a strange one, but he has helped defend us.\"", 5, nh_quest_bindings_112, 2},
    {"Bar", "hasamulet", "synopsis", "nethack.quest.bar.hasamulet.synopsis", "[\"Take the Amulet to the altar of %d on the Astral Plane and offer it.\"]", 0, nh_quest_bindings_113, 1},
    {"Bar", "hasamulet", "text", "nethack.quest.bar.hasamulet.text", "\"This is wondrous, %p.  I feared that you could not possibly\nsucceed in your quest, but here you are in possession of the Amulet\nof Yendor!\n\n\"I have studied the texts of the magi constantly since you left.  In\nthe Book of Skelos, I found this:\n\n    %d will cause a child to be sent into the world.  This child is to\n    be made strong by trial of battle and magic, for %d has willed it so.\n    It is said that the child of %d will recover the Amulet of Yendor\n    that was stolen from the Creator at the beginning of time.\n\n\"As you now possess the amulet, %p, I suspect that the Book\nspeaks of you.\n\n    The child of %d will take the Amulet, and travel to the Astral\n    Plane, where the Great Temple of %d is to be found.  The Amulet\n    will be sacrificed to %d, there on %dJ altar.  Then the child will\n    stand by %d as champion of all %cP for eternity.\n\n\"This is all I know, %p.  I hope it will help you.\"", 0, nh_quest_bindings_114, 5},
    {"Bar", "killed_nemesis", "synopsis", "nethack.quest.bar.killed_nemesis.synopsis", "[%nC curses you, but you feel the overpowering aura of magic fading.]", 0, nh_quest_bindings_115, 2},
    {"Bar", "killed_nemesis", "text", "nethack.quest.bar.killed_nemesis.text", "%nC falls to the ground, and utters a last curse at you.  Then %nj\nbody fades slowly, seemingly dispersing into the air around you.  You\nslowly become aware that the overpowering aura of magic in the air has\nbegun to fade.", 0, nh_quest_bindings_116, 3},
    {"Bar", "leader_first", "synopsis", "nethack.quest.bar.leader_first.synopsis", "[\"At last you have returned.  There is a great quest you must undertake.\"]", 0, NULL, 0},
    {"Bar", "leader_first", "text", "nethack.quest.bar.leader_first.text", "\"Ah, %p.  You have returned at last.  The world is in dire\nneed of your help.  There is a great quest you must undertake.\n\n\"But first, I must see if you are ready to take on such a challenge.\"", 0, nh_quest_bindings_118, 1},
    {"Bar", "leader_last", "synopsis", "nethack.quest.bar.leader_last.synopsis", "[\"You have betrayed %d; soon %n will destroy us.  Begone!\"]", 0, nh_quest_bindings_119, 2},
    {"Bar", "leader_last", "text", "nethack.quest.bar.leader_last.text", "\"Pah!  You have betrayed the gods, %p.  You will never attain\nthe glory which you aspire to.  Your failure to follow the true path has\nclosed this future to you.\n\n\"I will protect these people as best I can, but soon %n will overcome\nme and destroy all who once called you %s.  Now begone!\"", 0, nh_quest_bindings_120, 3},
    {"Bar", "leader_next", "text", "nethack.quest.bar.leader_next.text", "\"%p, you are back.  Are you ready now for the challenge?\"", 0, nh_quest_bindings_121, 1},
    {"Bar", "leader_other", "text", "nethack.quest.bar.leader_other.text", "\"Again, you stand before me, %p.  Surely you have prepared yourself.\"", 0, nh_quest_bindings_122, 1},
    {"Bar", "locate_first", "synopsis", "nethack.quest.bar.locate_first.synopsis", "[You have located %i.]", 0, nh_quest_bindings_123, 1},
    {"Bar", "locate_first", "text", "nethack.quest.bar.locate_first.text", "The scent of water comes to you in the desert breeze.  You know that\nyou have located %i.", 0, nh_quest_bindings_124, 1},
    {"Bar", "locate_next", "text", "nethack.quest.bar.locate_next.text", "Yet again you have a chance to infiltrate %i.", 0, nh_quest_bindings_125, 1},
    {"Bar", "nemesis_first", "synopsis", "nethack.quest.bar.nemesis_first.synopsis", "[%nC boasts that %nh has slain many.  \"Prepare to die, %c.\"]", 0, nh_quest_bindings_126, 4},
    {"Bar", "nemesis_first", "text", "nethack.quest.bar.nemesis_first.text", "\"So.  This is what that second rate sorcerer %l sends to do %lj bidding.\nI have slain many before you.  You shall give me little sport.\n\n\"Prepare to die, %c.\"", 0, nh_quest_bindings_127, 3},
    {"Bar", "nemesis_next", "text", "nethack.quest.bar.nemesis_next.text", "\"I have wasted too much time on you already.  Now, you shall die.\"", 0, NULL, 0},
    {"Bar", "nemesis_other", "text", "nethack.quest.bar.nemesis_other.text", "\"You return yet again, %c!  Are you prepared for death now?\"", 0, nh_quest_bindings_129, 1},
    {"Bar", "nemesis_wantsit", "text", "nethack.quest.bar.nemesis_wantsit.text", "\"I shall have %o back, you pitiful excuse for %ca.\nAnd your life as well.\"", 0, nh_quest_bindings_130, 3},
    {"Bar", "nexttime", "text", "nethack.quest.bar.nexttime.text", "Once again, you near %H.  You know that %l\nwill be waiting.", 0, nh_quest_bindings_131, 2},
    {"Bar", "offeredit", "synopsis", "nethack.quest.bar.offeredit.synopsis", "[%lC tells you to guard %o, and to return when you have triumphed.]", 0, nh_quest_bindings_132, 3},
    {"Bar", "offeredit", "text", "nethack.quest.bar.offeredit.text", "When %l sees %o, he smiles, and says:\n\n    Well done, %p.  You have saved the world from certain doom.\n    What, now, should be done with %o?\n\n    These people, brave as they are, cannot hope to guard it from\n    other sorcerers who will detect it, as surely as %n did.\n\n    Take %o with you, %p.  It will guard you in\n    your adventures, and you can best guard it.  You embark on a\n    quest far greater than you realize.\n\n    Remember me, %p, and return when you have triumphed.  I\n    will tell you then of what you must do.  You will understand when the\n    time comes.", 0, nh_quest_bindings_133, 4},
    {"Bar", "offeredit2", "synopsis", "nethack.quest.bar.offeredit2.synopsis", "[\"You keep %o.  Return to %Z to search for the Amulet.\"]", 0, nh_quest_bindings_134, 2},
    {"Bar", "offeredit2", "text", "nethack.quest.bar.offeredit2.text", "%l gazes reverently at %o, then back at you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  %Z await your return through the\nmagic portal which brought you here.\"", 0, nh_quest_bindings_135, 3},
    {"Bar", "othertime", "text", "nethack.quest.bar.othertime.text", "Again, and you think possibly for the last time, you approach\n%H.", 0, nh_quest_bindings_136, 1},
    {"Bar", "posthanks", "text", "nethack.quest.bar.posthanks.text", "\"Tell us, %p, have you fared well on your great quest?\"", 0, nh_quest_bindings_137, 1},
    {"Cav", "assignquest", "synopsis", "nethack.quest.cav.assignquest.synopsis", "[Find and defeat %n, recover %o, and return with it.]", 0, nh_quest_bindings_138, 2},
    {"Cav", "assignquest", "text", "nethack.quest.cav.assignquest.text", "\"You are indeed ready now, %p.  I shall tell you a tale of\ngreat suffering among your people:\n\n\"Shortly after you left on your vision quest, the caves were invaded by\nthe creatures sent against us by %n.\n\n\"She, herself, could not attack us due to her great size, but her minions\nhave harassed us ever since.  In the first attacks, many died, and the\nminions of %n managed to steal %o.\nThey took it to %i and there, none of our\n%g warriors have been able to go.\n\n\"You must find %i, and within it wrest\n%o from %n.  She guards it as\njealously as she guards all treasures she attains.  But with it,\nwe can make our caves safe once more.\n\n\"Please, %p, recover %o for us, and return it here.\"", 0, nh_quest_bindings_139, 5},
    {"Cav", "badalign", "synopsis", "nethack.quest.cav.badalign.synopsis", "[\"You no longer follow the path of the %a.  Go, and purify yourself.\"]", 0, nh_quest_bindings_140, 1},
    {"Cav", "badalign", "text", "nethack.quest.cav.badalign.text", "\"%pC!  You have deviated from my teachings.  You no longer follow\nthe path of the %a as you should.  I banish you from these caves, to\ngo forth and purify yourself.  Then, you might be able to accomplish this\nquest.\"", 0, nh_quest_bindings_141, 3},
    {"Cav", "badlevel", "synopsis", "nethack.quest.cav.badlevel.synopsis", "[\"%rA is too inexperienced.  Come back when you have progressed.\"]", 0, nh_quest_bindings_142, 2},
    {"Cav", "badlevel", "text", "nethack.quest.cav.badlevel.text", "\"Alas, %p, you are as yet too inexperienced to embark upon such\na difficult quest as that I propose to give you.\n\n\"%rA could not possibly survive the rigors demanded to find\n%i, never mind to confront %n herself.\n\n\"Adventure some more, and you will learn the skills you will require.\n%d decrees it.\"", 0, nh_quest_bindings_143, 6},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_1", "\"You are weak, %c.  No challenge for the Mother of all Dragons.\"", 1, nh_quest_bindings_144, 1},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_10", "\"%d has deserted you, %c.  This is my domain.\"", 10, nh_quest_bindings_145, 2},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_2", "\"I grow hungry, %r.  You look like a nice appetizer!\"", 2, nh_quest_bindings_146, 1},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_3", "\"Join me for lunch?  You're the main course, %c.\"", 3, nh_quest_bindings_147, 1},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_4", "\"With %o, I am invincible!  You cannot succeed.\"", 4, nh_quest_bindings_148, 1},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_5", "\"Your mentor, %l has failed.  You are nothing to fear.\"", 5, nh_quest_bindings_149, 1},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_6", "\"You shall die here, %c.  %rA cannot hope to defeat me.\"", 6, nh_quest_bindings_150, 3},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_7", "\"You, a mere %r challenge the might of %n?  Hah!\"", 7, nh_quest_bindings_151, 2},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_8", "\"I am the Mother of all Dragons!  You cannot hope to defeat me.\"", 8, NULL, 0},
    {"Cav", "discourage", "item", "nethack.quest.cav.discourage.item_9", "\"My claws are sharp now.  I shall rip you to shreds!\"", 9, NULL, 0},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_1", "\"%nC is immune to her own breath weapons. You should use magic upon her that she does not use herself.\"", 1, nh_quest_bindings_154, 2},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_10", "\"If only we had an amulet of reflection, this would not have happened.\"", 10, NULL, 0},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_2", "\"When you encounter %n, call upon %d for assistance.\"", 2, nh_quest_bindings_156, 2},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_3", "\"There will be nowhere to hide inside %ns inner sanctum.\"", 3, nh_quest_bindings_157, 2},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_4", "\"Your best chance with %n will be to keep moving.\"", 4, nh_quest_bindings_158, 1},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_5", "\"Do not be distracted by the great treasures in %ns lair. Concentrate on %o.\"", 5, nh_quest_bindings_159, 3},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_6", "\"%oC is the only object that %n truly fears.\"", 6, nh_quest_bindings_160, 3},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_7", "\"Do not be fooled by %ns size.  She is fast, and it is rumored that she uses magic.\"", 7, nh_quest_bindings_161, 2},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_8", "\"I would send a party of %gP with you, but we will need all of our strength to defend ourselves.\"", 8, nh_quest_bindings_162, 2},
    {"Cav", "encourage", "item", "nethack.quest.cav.encourage.item_9", "\"Remember, be %a at all times.  This is your strength.\"", 9, nh_quest_bindings_163, 1},
    {"Cav", "firsttime", "synopsis", "nethack.quest.cav.firsttime.synopsis", "[You arrive back at %H, but something is wrong here.]", 0, nh_quest_bindings_164, 1},
    {"Cav", "firsttime", "text", "nethack.quest.cav.firsttime.text", "You descend through a barely familiar stairwell that you remember\n%l showing you when you embarked upon your vision quest.\n\nYou arrive back at %H, but something seems\nwrong here.  The usual smoke and glowing light of the fires of the\nouter caves are absent, and an uneasy quiet fills the damp air.", 0, nh_quest_bindings_165, 2},
    {"Cav", "goal_first", "synopsis", "nethack.quest.cav.goal_first.synopsis", "[You enter a large cavern.  %nC is present.]", 0, nh_quest_bindings_166, 2},
    {"Cav", "goal_first", "text", "nethack.quest.cav.goal_first.text", "You find yourself in a large cavern, with neatly polished walls, that\nnevertheless show signs of being scorched by fire.\n\nBones litter the floor, and there are objects scattered everywhere.\nThe air is close with the stench of sulphurous fumes.\n\n%nC is clearly visible, but %nh seems to be asleep.", 0, nh_quest_bindings_167, 3},
    {"Cav", "goal_next", "text", "nethack.quest.cav.goal_next.text", "Once again, you find yourself in the lair of %n.", 0, nh_quest_bindings_168, 1},
    {"Cav", "gotit", "synopsis", "nethack.quest.cav.gotit.synopsis", "[%oC fills you with a feeling of power.]", 0, nh_quest_bindings_169, 2},
    {"Cav", "gotit", "text", "nethack.quest.cav.gotit.text", "As you pick up %o it seems heavy at first, but as you\nhold it strength flows into your arms.\n\nYou suddenly feel full of power, as if nothing could possibly stand\nin your path.", 0, nh_quest_bindings_170, 1},
    {"Cav", "guardtalk_after", "item", "nethack.quest.cav.guardtalk_after.item_1", "\"The rains have returned and the land grows lush again.\"", 1, NULL, 0},
    {"Cav", "guardtalk_after", "item", "nethack.quest.cav.guardtalk_after.item_2", "\"Peace has returned, give thanks to %d!\"", 2, nh_quest_bindings_172, 1},
    {"Cav", "guardtalk_after", "item", "nethack.quest.cav.guardtalk_after.item_3", "\"Welcome back!  Did you find %o?\"", 3, nh_quest_bindings_173, 1},
    {"Cav", "guardtalk_after", "item", "nethack.quest.cav.guardtalk_after.item_4", "\"So, %p, tell us the story of your fight with %n.\"", 4, nh_quest_bindings_174, 2},
    {"Cav", "guardtalk_after", "item", "nethack.quest.cav.guardtalk_after.item_5", "\"%lC grows old.  Perhaps you will guide us after he ascends.\"", 5, nh_quest_bindings_175, 2},
    {"Cav", "guardtalk_before", "item", "nethack.quest.cav.guardtalk_before.item_1", "\"We have not been able to gather as much food since the Giants sealed off our access to the outer world.\"", 1, NULL, 0},
    {"Cav", "guardtalk_before", "item", "nethack.quest.cav.guardtalk_before.item_2", "\"Since %n sent her minions, we have been constantly fighting.\"", 2, nh_quest_bindings_177, 1},
    {"Cav", "guardtalk_before", "item", "nethack.quest.cav.guardtalk_before.item_3", "\"I have heard your vision quest was successful.  Is this so?\"", 3, NULL, 0},
    {"Cav", "guardtalk_before", "item", "nethack.quest.cav.guardtalk_before.item_4", "\"So, tell me, %p, how have you fared?\"", 4, nh_quest_bindings_179, 1},
    {"Cav", "guardtalk_before", "item", "nethack.quest.cav.guardtalk_before.item_5", "\"%lC grows old.  We know not who will guide us after he ascends.\"", 5, nh_quest_bindings_180, 2},
    {"Cav", "hasamulet", "synopsis", "nethack.quest.cav.hasamulet.synopsis", "[\"Take the Amulet to the altar of %d on the Astral Plane and offer it.\"]", 0, nh_quest_bindings_181, 1},
    {"Cav", "hasamulet", "text", "nethack.quest.cav.hasamulet.text", "\"You have been successful, I see, %p.\n\n\"Now that the Amulet of Yendor is yours, here is what you must do:\n\n\"Journey upwards to the open air.  The Amulet you carry will then\ntake you into the Astral Planes, where the Great Temple of %d\ncasts its influence throughout our world.\n\n\"Sacrifice the Amulet on the altar.  Thus shall %d become supreme!\"", 0, nh_quest_bindings_182, 2},
    {"Cav", "killed_nemesis", "text", "nethack.quest.cav.killed_nemesis.text", "%nC sinks to the ground, her heads flailing about.\nAs she dies, a cloud of noxious fumes billows about her.", 0, nh_quest_bindings_183, 2},
    {"Cav", "leader_first", "synopsis", "nethack.quest.cav.leader_first.synopsis", "[\"You have returned.  We are in dire need of your help.\"]", 0, NULL, 0},
    {"Cav", "leader_first", "text", "nethack.quest.cav.leader_first.text", "\"You have returned from your vision quest, %p.  Thank %d.\n\n\"We are in dire need of your help, my %S.\n\n\"But first, I must see if you are yet capable of the quest I would\nask you to undertake.\"", 0, nh_quest_bindings_185, 3},
    {"Cav", "leader_last", "synopsis", "nethack.quest.cav.leader_last.synopsis", "[\"You have betrayed the %L.  Begone!\"]", 0, nh_quest_bindings_186, 1},
    {"Cav", "leader_last", "text", "nethack.quest.cav.leader_last.text", "\"%pC!  You have sealed our fate.  You seem unable to reform yourself,\nso I must select another to take your place.\n\n\"Begone from %H!  You have betrayed us by choosing\nthe path of the %C over the true path of the %L.\n\n\"You no longer live in our eyes.\"", 0, nh_quest_bindings_187, 5},
    {"Cav", "leader_next", "text", "nethack.quest.cav.leader_next.text", "\"Again, you return to us, %p.  Let me see if you are ready now.\"", 0, nh_quest_bindings_188, 1},
    {"Cav", "leader_other", "text", "nethack.quest.cav.leader_other.text", "\"Ah, %p.  Are you finally ready?\"", 0, nh_quest_bindings_189, 1},
    {"Cav", "locate_first", "synopsis", "nethack.quest.cav.locate_first.synopsis", "[You %x many large claw marks, smell carrion, and notice bones.]", 0, nh_quest_bindings_190, 1},
    {"Cav", "locate_first", "text", "nethack.quest.cav.locate_first.text", "You %x many large claw marks on the ground.  The tunnels ahead\nof you are larger than most of those in any cave complex you have\never been in before.\n\nYour nose detects the smell of carrion from within, and bones litter\nthe sides of the tunnels.", 0, nh_quest_bindings_191, 1},
    {"Cav", "locate_next", "text", "nethack.quest.cav.locate_next.text", "Once again, you approach %i.", 0, nh_quest_bindings_192, 1},
    {"Cav", "nemesis_first", "synopsis", "nethack.quest.cav.nemesis_first.synopsis", "[%nC threatens to eat you.]", 0, nh_quest_bindings_193, 2},
    {"Cav", "nemesis_first", "text", "nethack.quest.cav.nemesis_first.text", "\"So, follower of %l, you seek to invade the lair of\n%n.  Only my meals are allowed down here.  Prepare\nto be eaten!\"", 0, nh_quest_bindings_194, 2},
    {"Cav", "nemesis_next", "text", "nethack.quest.cav.nemesis_next.text", "\"So, again you face me, %c.  No one has ever before escaped me.\nNow I shall kill you.\"", 0, nh_quest_bindings_195, 1},
    {"Cav", "nemesis_other", "text", "nethack.quest.cav.nemesis_other.text", "\"You are getting annoying, %c.  Prepare to die.\"", 0, nh_quest_bindings_196, 1},
    {"Cav", "nemesis_wantsit", "text", "nethack.quest.cav.nemesis_wantsit.text", "\"I'll have %o from you, %c.  You shall die.\"", 0, nh_quest_bindings_197, 2},
    {"Cav", "nexttime", "text", "nethack.quest.cav.nexttime.text", "Once again, you arrive back at %H.", 0, nh_quest_bindings_198, 1},
    {"Cav", "offeredit", "synopsis", "nethack.quest.cav.offeredit.synopsis", "[\"Take %o with you.  It will help in your quest for the Amulet of Yendor.\"]", 0, nh_quest_bindings_199, 1},
    {"Cav", "offeredit", "text", "nethack.quest.cav.offeredit.text", "%lC glimpses %o in your possession.\nHe smiles and says:\n\n    You have done it!  We are saved.  But I fear that %o\n    will always be a target for %C forces who will want it for their\n    own.\n\n    To prevent further trouble, I would like you, %p,\n    to take %o away with you.  It will help you as you\n    quest for the Amulet of Yendor.", 0, nh_quest_bindings_200, 5},
    {"Cav", "offeredit2", "synopsis", "nethack.quest.cav.offeredit2.synopsis", "[\"You are the keeper of %o now.  Return to %Z to search for the Amulet.]", 0, nh_quest_bindings_201, 2},
    {"Cav", "offeredit2", "text", "nethack.quest.cav.offeredit2.text", "%l grasps %o proudly for a moment, then looks at you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  %Z await your return through the\nmagic portal which brought you here.\"", 0, nh_quest_bindings_202, 3},
    {"Cav", "othertime", "text", "nethack.quest.cav.othertime.text", "For some reason, you think that this may be the last time you will\nenter %H.", 0, nh_quest_bindings_203, 1},
    {"Cav", "posthanks", "text", "nethack.quest.cav.posthanks.text", "\"%pC!  Welcome back.\nHow goes your quest to recover the Amulet for %d?\"", 0, nh_quest_bindings_204, 3},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_1", "\"Repent, and thou shalt be saved!\"", 1, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_10", "\"No one expects the Spanish Inquisition!\"", 10, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_11", "\"Judgment hath been passed upon thee, %p.\"", 11, nh_quest_bindings_207, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_12", "\"Thy reckoning is at hand, %p.\"", 12, nh_quest_bindings_208, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_13", "\"Thou shalt be brought before %D for thy crimes!\"", 13, nh_quest_bindings_209, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_14", "\"With %D as my witness, I shall strike thee down.\"", 14, nh_quest_bindings_210, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_2", "\"Thou shalt pay for thine insolence!\"", 2, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_3", "\"Very soon, my child, thou shalt meet thy maker.\"", 3, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_4", "\"The great %D has sent me to make you pay for your sins!\"", 4, nh_quest_bindings_213, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_5", "\"The wrath of %D is now upon you!\"", 5, nh_quest_bindings_214, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_6", "\"Thy life belongs to %D now!\"", 6, nh_quest_bindings_215, 1},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_7", "\"Dost thou wish to receive thy final blessing?\"", 7, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_8", "\"Thou art but a godless void.\"", 8, NULL, 0},
    {"common", "angel_cuss", "item", "nethack.quest.common.angel_cuss.item_9", "\"Thou art not worthy to seek the Amulet.\"", 9, NULL, 0},
    {"common", "banished", "synopsis", "nethack.quest.common.banished.synopsis", "[You are banished from %H for betraying your allegiance to %d.]", 0, nh_quest_bindings_219, 2},
    {"common", "banished", "text", "nethack.quest.common.banished.text", "\"You have betrayed all those who hold allegiance to %d, as you once did.\nMy allegiance to %d holds fast and I cannot condone or accept what you\nhave done.\n\nLeave this place.  You shall never set foot at %H again.\nThat which you seek is now lost forever, for without the Bell of Opening,\nyou will never be able to enter the place where he who has the Amulet\nresides.\n\nGo now!  You are banished from this place.", 0, nh_quest_bindings_220, 2},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_1", "\"I first mistook thee for a statue, when I regarded thy head of stone.\"", 1, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_10", "\"I've met smarter (and prettier) acid blobs.\"", 10, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_11", "\"Look!  Thy bootlace is undone!\"", 11, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_12", "\"Mercy!  Dost thou wish me to die of laughter?\"", 12, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_13", "\"Run away!  Live to flee another day!\"", 13, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_14", "\"Thou hadst best fight better than thou canst dress!\"", 14, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_15", "\"Twixt thy cousin and thee, Medusa is the prettier.\"", 15, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_16", "\"Methinks thou wert unnaturally stirred by yon corpse back there, eh, varlet?\"", 16, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_17", "\"Up thy nose with a rubber hose!\"", 17, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_18", "\"Verily, thy corpse could not smell worse!\"", 18, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_19", "\"Wait!  I shall polymorph into a grid bug to give thee a fighting chance!\"", 19, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_2", "\"Come here often?\"", 2, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_20", "\"Why search for the Amulet?  Thou wouldst but lose it, cretin.\"", 20, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_21", "\"Thou ought to be a comedian, thy skills are so laughable!\"", 21, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_22", "\"Thy gaze is so vacant, I thought thee a floating eye!\"", 22, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_23", "\"Thy head is unfit for a mind flayer to munch upon!\"", 23, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_24", "\"Only thy reflection could love thee!\"", 24, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_25", "\"Hast thou considered masking thine odour?\"", 25, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_26", "\"Hold! Thy face is a most exquisite torture!\"", 26, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_27", "\"I should fart in thy direction, but it might improve thy smell!\"", 27, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_3", "\"Doth pain excite thee?  Wouldst thou prefer the whip?\"", 3, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_4", "\"Thinkest thou it shall tickle as I rip out thy lungs?\"", 4, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_5", "\"Eat slime and die!\"", 5, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_6", "\"Go ahead, fetch thy mama!  I shall wait.\"", 6, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_7", "\"Go play leapfrog with a herd of unicorns!\"", 7, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_8", "\"Hast thou been drinking, or art thou always so clumsy?\"", 8, NULL, 0},
    {"common", "demon_cuss", "item", "nethack.quest.common.demon_cuss.item_9", "\"This time I shall let thee off with a spanking, but let it not happen again.\"", 9, NULL, 0},
    {"common", "legacy", "synopsis", "nethack.quest.common.legacy.synopsis", "[%dC has chosen you to recover the Amulet of Yendor for %dI.]", 0, nh_quest_bindings_248, 3},
    {"common", "legacy", "text", "nethack.quest.common.legacy.text", "It is written in the Book of %d:\n\n    After the Creation, the cruel god Moloch rebelled\n    against the authority of Marduk the Creator.\n    Moloch stole from Marduk the most powerful of all\n    the artifacts of the gods, the Amulet of Yendor,\n    and he hid it in the dark cavities of Gehennom, the\n    Under World, where he now lurks, and bides his time.\n\nYour %G %d seeks to possess the Amulet, and with it\nto gain deserved ascendance over the other gods.\n\nYou, a newly trained %r, have been heralded\nfrom birth as the instrument of %d.  You are destined\nto recover the Amulet for your deity, or die in the\nattempt.  Your hour of destiny has come.  For the sake\nof us all:  Go bravely with %d!", 0, nh_quest_bindings_249, 3},
    {"common", "pauper_legacy", "synopsis", "nethack.quest.common.pauper_legacy.synopsis", "[%dC has chosen you to recover the Amulet of Yendor for %dI.]", 0, nh_quest_bindings_250, 3},
    {"common", "pauper_legacy", "text", "nethack.quest.common.pauper_legacy.text", "It is written in the Book of %d:\n\n    After the Creation, the cruel god Moloch rebelled\n    against the authority of Marduk the Creator.\n    Moloch stole from Marduk the most powerful of all\n    the artifacts of the gods, the Amulet of Yendor,\n    and he hid it in the dark cavities of Gehennom, the\n    Under World, where he now lurks, and bides his time.\n\nYour %G %d seeks to possess the Amulet, and with it\nto gain deserved ascendance over the other gods.\n\nYou, an untrained %r, have been unable to adequately\nprepare to be the instrument of %d.  Nevertheless, you\nare destined to recover the Amulet for your deity, or die\nin the attempt.  Your hour of destiny has come.  For the\nsake of us all:  Go bravely with %d!", 0, nh_quest_bindings_251, 3},
    {"common", "quest_complete_no_bell", "text", "nethack.quest.common.quest_complete_no_bell.text", "\"The silver bell which was hoarded by %n will be\nessential in locating the Amulet of Yendor.\"", 0, nh_quest_bindings_252, 1},
    {"common", "quest_portal", "text", "nethack.quest.common.quest_portal.text", "You receive a faint telepathic message from %l:\nYour help is urgently needed at %H!\nLook for a ...ic transporter.\nYou couldn't quite make out that last message.", 0, nh_quest_bindings_253, 2},
    {"common", "quest_portal_again", "text", "nethack.quest.common.quest_portal_again.text", "You again sense %l pleading for help.", 0, nh_quest_bindings_254, 1},
    {"common", "quest_portal_demand", "text", "nethack.quest.common.quest_portal_demand.text", "You again sense %l demanding your attendance.", 0, nh_quest_bindings_255, 1},
    {"common", "TEST_PATTERN", "text", "nethack.quest.common.test_pattern.text", "%p:\treturn(plname);\n %c:\treturn(pl_character);\n %r:\treturn((char *)rank_of(u.ulevel));\n %R:\treturn((char *)rank_of(MIN_QUEST_LEVEL));\n %s:\treturn((flags.female) ? \"sister\" : \"brother\" );\n %S:\treturn((flags.female) ? \"daughter\" : \"son\" );\n %l:\treturn((char *)ldrname());\n %i:\treturn(intermed());\n %o:\treturn(artiname());\n %O:\treturn(shortened(artiname()));\n %n:\treturn((char *)neminame());\n %g:\treturn((char *)guardname());\n %G:\treturn((char *)align_gtitle(u.ualignbase[1]));\n %H:\treturn((char *)homebase());\n %a:\treturn(Alignnam(u.ualignbase[1]));\n %A:\treturn(Alignnam(u.ualign.type));\n %d:\treturn((char *)align_gname(u.ualignbase[1]));\n %D:\treturn((char *)align_gname(A_LAWFUL));\n %C:\treturn(\"chaotic\");\n %N:\treturn(\"neutral\");\n %L:\treturn(\"lawful\");\n %x:\treturn((Blind) ? \"sense\" : \"see\");\n %Z:\treturn(\"The Dungeons of Doom\");\n %%:\treturn(percent_sign);\n a suffix:\treturn an(root);\n A suffix:\treturn An(root);\n C suffix:\treturn capitalized(root);\n h suffix:\treturn pronoun(he_or_she, mon_of(root)); /* for %l,%n,%d,%o */\n H suffix:\treturn capitalized(pronoun(he_or_she, mon_of(root)));\n i suffix:\treturn pronoun(him_or_her, mon_of(root));\n I suffix:\treturn capitalized(pronoun(him_or_her, mon_of(root)));\n j suffix:\treturn pronoun(his_or_her, mon_of(root));\n J suffix:\treturn capitalized(pronoun(his_or_her, mon_of(root)));\n p suffix:\treturn makeplural(root);\n P suffix:\treturn makeplural(capitalized(root));\n s suffix:\treturn s_suffix(root);\n S suffix:\treturn s_suffix(capitalized(root));\n t suffix:\treturn strip_the_prefix(root);", 0, nh_quest_bindings_256, 23},
    {"Hea", "assignquest", "synopsis", "nethack.quest.hea.assignquest.synopsis", "[Travel to %i on your way to recover %o from %n.]", 0, nh_quest_bindings_257, 3},
    {"Hea", "assignquest", "text", "nethack.quest.hea.assignquest.text", "For the first time, you sense a smile on %ls face.\n\n    \"You have indeed learned as much as we can teach you in preparation\n    for this task.  Let me tell you what I know of the symptoms and hope\n    that you can provide a cure.\n\n    \"A short while ago, the dreaded %nt was fooled by the gods\n    into thinking that %nh could use %o to find a\n    cure for old age.  Think of it, eternal youth!  But %nj good\n    health is accomplished by drawing the health from those around %ni.\n\n    \"He has exhausted %nj own supply of healthy people and now %nh seeks to\n    extend %nj influence into our world.  You must recover from %ni\n    %o and break the spell.\n\n    \"You must travel into the swamps to %i, and from there\n    follow the trail to %ns island lair.  Be careful.\"", 0, nh_quest_bindings_258, 10},
    {"Hea", "badalign", "synopsis", "nethack.quest.hea.badalign.synopsis", "[Return when you are more %a.]", 0, nh_quest_bindings_259, 1},
    {"Hea", "badalign", "text", "nethack.quest.hea.badalign.text", "\"You have learned much of the remedies that benefit, but you must also\nknow which physic for which ail.  That is why %ds teachings are a\npart of your training.\n\n\"Return to us when you have healed thyself.\"", 0, nh_quest_bindings_260, 2},
    {"Hea", "badlevel", "synopsis", "nethack.quest.hea.badlevel.synopsis", "[You are too inexperienced.  Return when you are %Ra.]", 0, nh_quest_bindings_261, 2},
    {"Hea", "badlevel", "text", "nethack.quest.hea.badlevel.text", "\"Alas, %p, you are yet too inexperienced to deal with the rigors\nof such a task.  You must be able to draw on the knowledge of botany,\nalchemy and veterinary practices before I can send you on this quest \nwith good conscience.\n\n\"Return when you wear %Ra's caduceus.\"", 0, nh_quest_bindings_262, 2},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_1", "\"They might as well give scalpels to wizards as to let you try to use %o!\"", 1, nh_quest_bindings_263, 1},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_10", "\"You should have stopped studying at veterinary.\"", 10, NULL, 0},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_2", "\"If I could strike %l, surrounded by %lj %gP, imagine what I can do to you here by yourself.\"", 2, nh_quest_bindings_265, 3},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_3", "\"I will put my %Rp to work making a physic out of your ashes.\"", 3, nh_quest_bindings_266, 1},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_4", "\"As we speak, Hades gathers your patients to join you.\"", 4, NULL, 0},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_5", "\"After I'm done with you, I'll destroy %l as well.\"", 5, nh_quest_bindings_268, 1},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_6", "\"You will have to kill me if you ever hope to leave this place.\"", 6, NULL, 0},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_7", "\"I will impale your head on my caduceus for all to see.\"", 7, NULL, 0},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_8", "\"There is no materia medica in your sack which will cure you of me!\"", 8, NULL, 0},
    {"Hea", "discourage", "item", "nethack.quest.hea.discourage.item_9", "\"Do not fight too hard, I want your soul strong, not weakened!\"", 9, NULL, 0},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_1", "\"Remember, %p, to always wash your hands before operating.\"", 1, nh_quest_bindings_273, 1},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_10", "\"With but one eye, %n should be easy to blind.  Remember this.\"", 10, nh_quest_bindings_274, 1},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_2", "\"%nC has no real magic of %nj own.  To this %nh is vulnerable.\"", 2, nh_quest_bindings_275, 4},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_3", "\"If you have been true to %d, you can draw on the power of %o.\"", 3, nh_quest_bindings_276, 2},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_4", "\"Bring with you antidotes for poisons.\"", 4, NULL, 0},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_5", "\"Remember this, %n can twist the powers of %o to hurt instead of heal.\"", 5, nh_quest_bindings_278, 2},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_6", "\"I have sent for Chiron, but I am afraid he will come too late.\"", 6, NULL, 0},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_7", "\"Maybe when you return the snakes will once again begin to shed.\"", 7, NULL, 0},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_8", "\"The plague grows worse as we speak.  Hurry, %p!\"", 8, nh_quest_bindings_281, 1},
    {"Hea", "encourage", "item", "nethack.quest.hea.encourage.item_9", "\"Many times %n has caused trouble in these lands.  It is time that %nh was eradicated like the diseases %nh has caused.\"", 9, nh_quest_bindings_282, 2},
    {"Hea", "firsttime", "synopsis", "nethack.quest.hea.firsttime.synopsis", "[You arrive back at %H and must find %l.]", 0, nh_quest_bindings_283, 2},
    {"Hea", "firsttime", "text", "nethack.quest.hea.firsttime.text", "What sorcery has brought you back to %H?  The smell\nof fresh funeral pyres tells you that something is amiss with the healing\npowers that used to practice here.\n\nNo rhizotomists are tending the materia medica gardens, and where are the\ncommon folk who used to come for the cures?\n\nYou know that you must quickly make your way to the collegium, and\n%ls iatreion, and find out what has happened in your absence.", 0, nh_quest_bindings_284, 3},
    {"Hea", "goal_first", "synopsis", "nethack.quest.hea.goal_first.synopsis", "[You have reached the lair of %n.  Take %o away from %ni.]", 0, nh_quest_bindings_285, 3},
    {"Hea", "goal_first", "text", "nethack.quest.hea.goal_first.text", "You stand within sight of the infamous Isle of %n.  Even\nthe words of %l had not prepared you for this.\n\nSteeling yourself against the wails of the ill that pierce your ears,\nyou hurry on your task.  Maybe with %o you can\nheal them on your return, but not now.", 0, nh_quest_bindings_286, 3},
    {"Hea", "goal_next", "text", "nethack.quest.hea.goal_next.text", "Once again, you %x the Isle of %n in the distance.", 0, nh_quest_bindings_287, 2},
    {"Hea", "gotit", "synopsis", "nethack.quest.hea.gotit.synopsis", "[You feel the healing power of %o and should return it to %l.]", 0, nh_quest_bindings_288, 2},
    {"Hea", "gotit", "text", "nethack.quest.hea.gotit.text", "As you pick up %o, you feel its healing begin to\nwarm your soul.  You curse Zeus for taking it from its rightful owner,\nbut at least you hope that %l can put it to good use once\nagain.", 0, nh_quest_bindings_289, 2},
    {"Hea", "guardtalk_after", "item", "nethack.quest.hea.guardtalk_after.item_1", "\"Did you read that new treatise on the therapeutic use of leeches?\"", 1, NULL, 0},
    {"Hea", "guardtalk_after", "item", "nethack.quest.hea.guardtalk_after.item_2", "\"Paint a red caduceus on your shield and monsters won't hit you.\"", 2, NULL, 0},
    {"Hea", "guardtalk_after", "item", "nethack.quest.hea.guardtalk_after.item_3", "\"How are you feeling?  Perhaps a good bleeding will improve your spirits.\"", 3, NULL, 0},
    {"Hea", "guardtalk_after", "item", "nethack.quest.hea.guardtalk_after.item_4", "\"Have you heard the absurd new theory that diseases are caused by microscopic organisms, and not ill humors?\"", 4, NULL, 0},
    {"Hea", "guardtalk_after", "item", "nethack.quest.hea.guardtalk_after.item_5", "\"I see that you bring %o, now you can cure this plague!\"", 5, nh_quest_bindings_294, 1},
    {"Hea", "guardtalk_before", "item", "nethack.quest.hea.guardtalk_before.item_1", "\"Did you read that new treatise on the therapeutic use of leeches?\"", 1, NULL, 0},
    {"Hea", "guardtalk_before", "item", "nethack.quest.hea.guardtalk_before.item_2", "\"Paint a red caduceus on your shield and monsters won't hit you.\"", 2, NULL, 0},
    {"Hea", "guardtalk_before", "item", "nethack.quest.hea.guardtalk_before.item_3", "\"I passed handwriting so they are demoting me a rank.\"", 3, NULL, 0},
    {"Hea", "guardtalk_before", "item", "nethack.quest.hea.guardtalk_before.item_4", "\"I've heard that even %l has not been able to cure Chiron.\"", 4, nh_quest_bindings_298, 1},
    {"Hea", "guardtalk_before", "item", "nethack.quest.hea.guardtalk_before.item_5", "\"We think %n has used %nj alchemists, and %o, to unleash a new disease we call 'the cold' on Gehennom.\"", 5, nh_quest_bindings_299, 3},
    {"Hea", "hasamulet", "synopsis", "nethack.quest.hea.hasamulet.synopsis", "[\"You have recovered the Amulet.  Travel to the Astral Plane and return it to %d.\"]", 0, nh_quest_bindings_300, 1},
    {"Hea", "hasamulet", "text", "nethack.quest.hea.hasamulet.text", "\"Ah, you have recovered the Amulet, %p.  Well done!\n\n\"Now, you should know that you must travel through the Elemental Planes\nto the Astral, and there return the Amulet to %d.  Go forth and\nmay our prayers be as a wind upon your back.\"", 0, nh_quest_bindings_301, 2},
    {"Hea", "killed_nemesis", "synopsis", "nethack.quest.hea.killed_nemesis.synopsis", "[%nC curses you as %nh dies.]", 0, nh_quest_bindings_302, 3},
    {"Hea", "killed_nemesis", "text", "nethack.quest.hea.killed_nemesis.text", "The battered body of %n slumps to the ground and gasps\nout one last curse:\n\n    \"You have defeated me, %p, but I shall have my revenge.\n    How, I shall not say, but this curse shall be like a cancer\n    on you.\"\n\nWith that %n dies.", 0, nh_quest_bindings_303, 2},
    {"Hea", "leader_first", "synopsis", "nethack.quest.hea.leader_first.synopsis", "[%l is weak from the struggle with %n.  %lH wants to examine you.]", 0, nh_quest_bindings_304, 3},
    {"Hea", "leader_first", "text", "nethack.quest.hea.leader_first.text", "Feebly, %l raises %lj head to look at you.\n\n\"It is good to see you again, %p.  I see the concern in your\neyes, but do not worry for me.  I am not ready for Hades yet.  We have\nexhausted much of our healing powers holding off %n.\nI need your fresh strength to carry on our work.\n\n\"Come closer and let me lay hands on you, and determine if you have\nthe skills necessary to accomplish this mission.\"", 0, nh_quest_bindings_305, 4},
    {"Hea", "leader_last", "synopsis", "nethack.quest.hea.leader_last.synopsis", "[You are a failure as a healer.]", 0, NULL, 0},
    {"Hea", "leader_last", "text", "nethack.quest.hea.leader_last.text", "\"You have failed us, %p.  You are a quack!  A charlatan!\n\n\"Hades will be happy to hear that you are once again practicing your\narts on the unsuspecting.\"", 0, nh_quest_bindings_307, 1},
    {"Hea", "leader_next", "text", "nethack.quest.hea.leader_next.text", "\"Again you return to me, %p.  I sense that each trip back\nthe pleurisy and maladies of our land begin to infect you.  Let us\nhope and pray to %d that you become ready for your task before\nyou fall victim to the bad humors.\"", 0, nh_quest_bindings_308, 2},
    {"Hea", "leader_other", "text", "nethack.quest.hea.leader_other.text", "\"Chiron has fallen, Hermes has fallen, what else must I tell you to\nimpress upon you the importance of your mission!  I hope that you\nhave come prepared this time.\"", 0, NULL, 0},
    {"Hea", "locate_first", "synopsis", "nethack.quest.hea.locate_first.synopsis", "[You have reached %i but all is not well.]", 0, nh_quest_bindings_310, 1},
    {"Hea", "locate_first", "text", "nethack.quest.hea.locate_first.text", "You stand before the entrance to %i.  Strange\nscratching noises come from within the building.\n\nThe swampy ground around you seems to stink with disease.", 0, nh_quest_bindings_311, 1},
    {"Hea", "locate_next", "text", "nethack.quest.hea.locate_next.text", "Once again you stand at the entrance to %i.", 0, nh_quest_bindings_312, 1},
    {"Hea", "nemesis_first", "synopsis", "nethack.quest.hea.nemesis_first.synopsis", "[\"I will take your life, then defeat %l.\"]", 0, nh_quest_bindings_313, 1},
    {"Hea", "nemesis_first", "text", "nethack.quest.hea.nemesis_first.text", "\"They have made a mistake in sending you, %p.\n\n\"When I add your youth to mine, it will just make it easier for me\nto defeat %l.\"", 0, nh_quest_bindings_314, 2},
    {"Hea", "nemesis_next", "text", "nethack.quest.hea.nemesis_next.text", "\"Unlike your patients, you seem to keep coming back, %p!\"", 0, nh_quest_bindings_315, 1},
    {"Hea", "nemesis_other", "text", "nethack.quest.hea.nemesis_other.text", "\"Which would you like, %p?  Boils, pleurisy, convulsions?\"", 0, nh_quest_bindings_316, 1},
    {"Hea", "nemesis_wantsit", "text", "nethack.quest.hea.nemesis_wantsit.text", "\"I'll have %o back from you, %r.  You are\nnot going to live to escape this place.\"", 0, nh_quest_bindings_317, 2},
    {"Hea", "nexttime", "text", "nethack.quest.hea.nexttime.text", "After your last experience you expected to be here, but you certainly\ndid not expect to see things so much worse.  This time you must succeed.", 0, NULL, 0},
    {"Hea", "offeredit", "synopsis", "nethack.quest.hea.offeredit.synopsis", "[%l touches %o and tells %lj %gP to do so too, then tells you to take it with you.]", 0, nh_quest_bindings_319, 5},
    {"Hea", "offeredit", "text", "nethack.quest.hea.offeredit.text", "As soon as %l sees %o %lh summons %lj\n%gP.\n\nGently, %l reaches out and touches %o.\nHe instructs each of the assembled to do the same.  When everyone\nhas finished %lh speaks to you.\n\n    \"Now that we have been replenished we can defeat this plague.  You must\n    take %o with you and replenish the worlds you have\n    been called upon to travel next.  I wish you could ride Chiron to the\n    end of your journey, but I need him to help me spread the cure.  Go\n    now and continue your journey.\"", 0, nh_quest_bindings_320, 5},
    {"Hea", "offeredit2", "synopsis", "nethack.quest.hea.offeredit2.synopsis", "[%l tells you to keep %o and return to %Z to search for the Amulet.]", 0, nh_quest_bindings_321, 3},
    {"Hea", "offeredit2", "text", "nethack.quest.hea.offeredit2.text", "%l cautiously handles %o while watching you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  %Z await your return through the\nmagic portal which brought you here.\"", 0, nh_quest_bindings_322, 3},
    {"Hea", "othertime", "text", "nethack.quest.hea.othertime.text", "Again, you %x %H in the distance.\n\nThe smell of death and disease permeates the air.  You do not have\nto be %Ra to know that %n is on the verge of victory.", 0, nh_quest_bindings_323, 4},
    {"Hea", "posthanks", "text", "nethack.quest.hea.posthanks.text", "\"You have again returned to us, %p.  We have done well in your\nabsence, yes?  How fare you upon your quest for the Amulet?\"", 0, nh_quest_bindings_324, 1},
    {"Kni", "assignquest", "synopsis", "nethack.quest.kni.assignquest.synopsis", "[Pass through %i to reach %n.  Destroy %ni and return with %o.]", 0, nh_quest_bindings_325, 4},
    {"Kni", "assignquest", "text", "nethack.quest.kni.assignquest.text", "\"Ah, %p.  Thou art truly ready, as no %c before thee hath\nbeen.  Hear now Our words:\n\n\"As thou noticed as thou approached %H, a great battle hath\nbeen fought recently in these fields.  Know thou that Merlin himself\ncame to aid Us here as We battled the foul %n.  In the midst of that\nbattle, %n struck Merlin a great blow, felling him.  Then, as Our\nforces were pressed back, %n stole %o.\n\n\"We eventually turned the tide, but lost many %cP in doing so.\nMerlin was taken off by his apprentice, but hath not recovered.  We have\nbeen told that so long as %n possesseth %o,\nMerlin will not regain his health.\n\n\"We hereby charge thee with this most important of duties:\n\n\"Go forth from this place, to the fens, and there thou wilt find\n%i.  From there, thou must track down %n.  Destroy the\nbeast, and return to Us %o.  Only then can\nWe restore Merlin to health.\"", 0, nh_quest_bindings_326, 7},
    {"Kni", "badalign", "synopsis", "nethack.quest.kni.badalign.synopsis", "[Go and do penance.  Return when you are truly %a.]", 0, nh_quest_bindings_327, 1},
    {"Kni", "badalign", "text", "nethack.quest.kni.badalign.text", "\"Thou dishonourest Us, %p!  Thou hast strayed from the path of\nchivalry! Go from Our presence and do penance.  Only when thou art again\npure mayst thou return hence.\"", 0, nh_quest_bindings_328, 1},
    {"Kni", "badlevel", "synopsis", "nethack.quest.kni.badlevel.synopsis", "[You are not prepared to face %n.  Return when you are %Ra.]", 0, nh_quest_bindings_329, 3},
    {"Kni", "badlevel", "text", "nethack.quest.kni.badlevel.text", "\"Verily, %p, thou hast done well.  That thou hast survived thus\nfar is a credit to thy valor, but thou art yet unprepared for\nthe demands required as Our Champion.  %rA, no matter how\npure, could never hope to defeat the foul %n.\n\n\"Journey forth from this place, and hone thy skills.  Return to\nOur presence when thou hast attained the noble title of %R.\"", 0, nh_quest_bindings_330, 4},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_1", "\"A mere %r can never withstand me!\"", 1, nh_quest_bindings_331, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_10", "\"Call upon thy precious %d, %p.  It shall not avail thee.\"", 10, nh_quest_bindings_332, 2},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_2", "\"I shall kill thee now, and feast!\"", 2, NULL, 0},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_3", "\"Puny %c.  What manner of death dost thou wish?\"", 3, nh_quest_bindings_334, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_4", "\"First thee, %p, then I shall feast upon %l.\"", 4, nh_quest_bindings_335, 2},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_5", "\"Hah!  Thou hast failed, %r.  Now thou shalt die.\"", 5, nh_quest_bindings_336, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_6", "\"Die, %c.  Thou art as nothing against my might.\"", 6, nh_quest_bindings_337, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_7", "\"I shall suck the marrow from thy bones, %c.\"", 7, nh_quest_bindings_338, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_8", "\"Let's see...  Baked?  No.  Fried?  Nay.  Broiled?  Yea verily, that is the way I like my %c for dinner.\"", 8, nh_quest_bindings_339, 1},
    {"Kni", "discourage", "item", "nethack.quest.kni.discourage.item_9", "\"Thy strength waneth, %p.  The time of thy death draweth near.\"", 9, nh_quest_bindings_340, 1},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_1", "\"Remember, %p, follow always the path of %d.\"", 1, nh_quest_bindings_341, 2},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_10", "\"To find %i, thou must keep thy heart pure.\"", 10, nh_quest_bindings_342, 1},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_2", "\"Though %n is verily a mighty foe, We have confidence in thy victory.\"", 2, nh_quest_bindings_343, 1},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_3", "\"Beware, for %n hath surrounded %niself with hordes of foul creatures.\"", 3, nh_quest_bindings_344, 2},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_4", "\"Great treasure, 'tis said, is hoarded in the lair of %n.\"", 4, nh_quest_bindings_345, 1},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_5", "\"If thou possessest %o, %p, %ns magic shall therewith be thwarted.\"", 5, nh_quest_bindings_346, 4},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_6", "\"The gates of %i are guarded by forces unseen, %p. Go carefully.\"", 6, nh_quest_bindings_347, 2},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_7", "\"Return %o to Us quickly, %p.\"", 7, nh_quest_bindings_348, 2},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_8", "\"Destroy %n, %p, else %H shall surely fall.\"", 8, nh_quest_bindings_349, 3},
    {"Kni", "encourage", "item", "nethack.quest.kni.encourage.item_9", "\"Call upon %d when thou art in need.\"", 9, nh_quest_bindings_350, 1},
    {"Kni", "firsttime", "synopsis", "nethack.quest.kni.firsttime.synopsis", "[Signs of battle include long gouges in the walls of %H.]", 0, nh_quest_bindings_351, 1},
    {"Kni", "firsttime", "text", "nethack.quest.kni.firsttime.text", "You materialize in the shadows of %H.  Immediately, you notice\nthat something is wrong.  The fields around the castle are trampled and\nwithered, as if some great battle has been recently fought.\n\nExploring further, you %x long gouges in the walls of %H.\nYou know of only one creature that makes those kinds of marks...", 0, nh_quest_bindings_352, 2},
    {"Kni", "goal_first", "synopsis", "nethack.quest.kni.goal_first.synopsis", "[You %x the entrance to a cavern inside a hill.]", 0, nh_quest_bindings_353, 1},
    {"Kni", "goal_first", "text", "nethack.quest.kni.goal_first.text", "As you exit the swamps, you %x before you a huge, gaping hole in the\nside of a hill.  From within, you smell the foul stench of carrion.\n\nThe pools on either side of the entrance are fouled with blood, and\npieces of rusted metal and broken weapons show above the surface.", 0, nh_quest_bindings_354, 1},
    {"Kni", "goal_next", "text", "nethack.quest.kni.goal_next.text", "Again, you stand at the entrance to %ns lair.", 0, nh_quest_bindings_355, 2},
    {"Kni", "gotit", "synopsis", "nethack.quest.kni.gotit.synopsis", "[You feel the magic of %o.]", 0, nh_quest_bindings_356, 1},
    {"Kni", "gotit", "text", "nethack.quest.kni.gotit.text", "As you pick up %o, you feel its protective fields\nform around your body.  You also feel a faint stirring in your mind, as\nif you are in two places at once, and in the second, you are waking from\na long sleep.", 0, nh_quest_bindings_357, 1},
    {"Kni", "guardtalk_after", "item", "nethack.quest.kni.guardtalk_after.item_1", "\"Hail, %p!  Verily, thou lookest well.\"", 1, nh_quest_bindings_358, 1},
    {"Kni", "guardtalk_after", "item", "nethack.quest.kni.guardtalk_after.item_2", "\"So, %p, didst thou find %n in the fens near %i?\"", 2, nh_quest_bindings_359, 3},
    {"Kni", "guardtalk_after", "item", "nethack.quest.kni.guardtalk_after.item_3", "\"Worthy %p, hast thou proven thy right purpose on the body of %n?\"", 3, nh_quest_bindings_360, 2},
    {"Kni", "guardtalk_after", "item", "nethack.quest.kni.guardtalk_after.item_4", "\"Verily, %l could have no better champion, %p.\"", 4, nh_quest_bindings_361, 2},
    {"Kni", "guardtalk_after", "item", "nethack.quest.kni.guardtalk_after.item_5", "\"Hast thou indeed recovered %o?\"", 5, nh_quest_bindings_362, 1},
    {"Kni", "guardtalk_before", "item", "nethack.quest.kni.guardtalk_before.item_1", "\"Hail, %p!  Verily, thou lookest well.\"", 1, nh_quest_bindings_363, 1},
    {"Kni", "guardtalk_before", "item", "nethack.quest.kni.guardtalk_before.item_2", "\"There is word, %p, that %n hath been sighted in the fens near %i.\"", 2, nh_quest_bindings_364, 3},
    {"Kni", "guardtalk_before", "item", "nethack.quest.kni.guardtalk_before.item_3", "\"Thou art our only hope now, %p.\"", 3, nh_quest_bindings_365, 1},
    {"Kni", "guardtalk_before", "item", "nethack.quest.kni.guardtalk_before.item_4", "\"Verily, %l could have no better champion, %p.\"", 4, nh_quest_bindings_366, 2},
    {"Kni", "guardtalk_before", "item", "nethack.quest.kni.guardtalk_before.item_5", "\"Many brave %cP died when %n attacked.\"", 5, nh_quest_bindings_367, 2},
    {"Kni", "hasamulet", "synopsis", "nethack.quest.kni.hasamulet.synopsis", "[Take the Amulet to the Astral Plane and deliver it to %d.]", 0, nh_quest_bindings_368, 1},
    {"Kni", "hasamulet", "text", "nethack.quest.kni.hasamulet.text", "\"Thou hast succeeded, We see, %p!  Now thou art commanded to take\nthe Amulet to be sacrificed to %d in the Plane of the Astral.\n\n\"Merlin hath counseled Us that thou must travel always upwards through\nthe Planes of the Elements, to achieve this goal.\n\n\"Go with %d, %p.\"", 0, nh_quest_bindings_369, 2},
    {"Kni", "killed_nemesis", "synopsis", "nethack.quest.kni.killed_nemesis.synopsis", "[%nC curses you as %nh dies.]", 0, nh_quest_bindings_370, 3},
    {"Kni", "killed_nemesis", "text", "nethack.quest.kni.killed_nemesis.text", "As %n sinks to the ground, blood gushing from %nj open mouth, %nh\ndefiantly curses you and %l:\n\n    \"Thou hast not won yet, %r.  By the gods, I shall return\n    and dog thy steps to the grave!\"\n\n%nJ tail flailing madly, %n tries to crawl towards you, but slumps\nto the ground and dies in a pool of %nj own blood.", 0, nh_quest_bindings_371, 6},
    {"Kni", "leader_first", "synopsis", "nethack.quest.kni.leader_first.synopsis", "[%lC checks whether you are ready for a great undertaking.]", 0, nh_quest_bindings_372, 2},
    {"Kni", "leader_first", "text", "nethack.quest.kni.leader_first.text", "\"Ah, %p.  We see thou hast received Our summons.\nWe are in dire need of thy prowess.  But first, We must needs\ndecide if thou art ready for this great undertaking.\"", 0, nh_quest_bindings_373, 1},
    {"Kni", "leader_last", "synopsis", "nethack.quest.kni.leader_last.synopsis", "[You are a disgrace as %ca.]", 0, nh_quest_bindings_374, 2},
    {"Kni", "leader_last", "text", "nethack.quest.kni.leader_last.text", "\"Thou disgracest this noble court with thine impure presence.  We have been\nlenient with thee, but no more.  Thy name shall be spoken no more.  We\nhereby strip thee of thy title, thy lands, and thy standing as %ca.\nBegone from Our sight!\"", 0, nh_quest_bindings_375, 2},
    {"Kni", "leader_next", "text", "nethack.quest.kni.leader_next.text", "\"Welcome again, %p.  We hope thou art ready now.\"", 0, nh_quest_bindings_376, 1},
    {"Kni", "leader_other", "text", "nethack.quest.kni.leader_other.text", "\"Once again, thou standest before Us, %p.  Art thou ready now?\"", 0, nh_quest_bindings_377, 1},
    {"Kni", "locate_first", "synopsis", "nethack.quest.kni.locate_first.synopsis", "[You have reached %i and can %x a shrine.]", 0, nh_quest_bindings_378, 2},
    {"Kni", "locate_first", "text", "nethack.quest.kni.locate_first.text", "You stand at the foot of %i.  Atop, you can %x a shrine.\nStrange energies seem to be focused here, and the hair on the back of\nyour neck stands on end.", 0, nh_quest_bindings_379, 2},
    {"Kni", "locate_next", "text", "nethack.quest.kni.locate_next.text", "Again, you stand at the foot of %i.", 0, nh_quest_bindings_380, 1},
    {"Kni", "nemesis_first", "synopsis", "nethack.quest.kni.nemesis_first.synopsis", "[%nC taunts you and issues a threat against %H.]", 0, nh_quest_bindings_381, 3},
    {"Kni", "nemesis_first", "text", "nethack.quest.kni.nemesis_first.text", "\"Hah!  Another puny %c seeks death.  I shall dine well tonight,\nthen tomorrow, %H shall fall!\"", 0, nh_quest_bindings_382, 2},
    {"Kni", "nemesis_next", "text", "nethack.quest.kni.nemesis_next.text", "\"Again, thou challengest me, %r?  So be it.  Thou wilt die here.\"", 0, nh_quest_bindings_383, 1},
    {"Kni", "nemesis_other", "text", "nethack.quest.kni.nemesis_other.text", "\"Thou art truly foolish, %r.  I shall dispatch thee anon.\"", 0, nh_quest_bindings_384, 1},
    {"Kni", "nemesis_wantsit", "text", "nethack.quest.kni.nemesis_wantsit.text", "\"So, thou darest touch MY property!  I shall have that bauble back,\npuny %r.  Thou wilt die in agony!\"", 0, nh_quest_bindings_385, 1},
    {"Kni", "nexttime", "text", "nethack.quest.kni.nexttime.text", "Once again you stand in the shadows of %H.", 0, nh_quest_bindings_386, 1},
    {"Kni", "offeredit", "synopsis", "nethack.quest.kni.offeredit.synopsis", "[%oC is yours now.  It will aid in your search for the Amulet.]", 0, nh_quest_bindings_387, 2},
    {"Kni", "offeredit", "text", "nethack.quest.kni.offeredit.text", "As you approach %l, %lh beams at you and says:\n\n    \"Well done!  Thou art truly the Champion of %H.  We\n    have received word that Merlin is recovering, and shall soon\n    rejoin Us.\n\n    \"He hath instructed Us that thou art now to be the guardian of\n    %o.  He feeleth that thou mayst have need of\n    its powers in thine adventures.  It is Our wish that thou keepest\n    %o with thee as thou searchest for the fabled\n    Amulet of Yendor.\"", 0, nh_quest_bindings_388, 4},
    {"Kni", "offeredit2", "synopsis", "nethack.quest.kni.offeredit2.synopsis", "[You are the keeper of %o.  Return to %Z and find the Amulet.]", 0, nh_quest_bindings_389, 2},
    {"Kni", "offeredit2", "text", "nethack.quest.kni.offeredit2.text", "\"Careful, %p!  %oC might break, and that would\nbe a tragic loss.  Thou art its keeper now, and the time hath come\nto resume thy search for the Amulet.  %Z await thy\nreturn through the magic portal that brought thee here.\"", 0, nh_quest_bindings_390, 4},
    {"Kni", "othertime", "text", "nethack.quest.kni.othertime.text", "Again, you stand before %H.  You vaguely sense that this\nmay be the last time you stand before %l.", 0, nh_quest_bindings_391, 2},
    {"Kni", "posthanks", "text", "nethack.quest.kni.posthanks.text", "\"Well met, %p.  How goeth thy search for the Amulet of Yendor?\"", 0, nh_quest_bindings_392, 1},
    {"Mon", "assignquest", "synopsis", "nethack.quest.mon.assignquest.synopsis", "[Find %i, then continue to %ns lair.  Defeat %ni and return with %o.]", 0, nh_quest_bindings_393, 5},
    {"Mon", "assignquest", "text", "nethack.quest.mon.assignquest.text", "\"Yes, %p.  You are truly ready now.  Attend to me and I shall\ntell you of what has transpired:\n\n\"During one of the Great Meditations a short time ago, %n and\na legion of elementals invaded %H.  Many %gP\nwere killed, including the one bearing %o.\n\nNow, there are barely enough %gP left to keep the elementals\nat bay.\n\n\"We need you to find %i, then, from there,\ntravel to %ns lair.  If you can manage to defeat %n and\nreturn %o here, we can then drive off the legions\nof elementals that slay our students.\n\n\"Go with %d as your guide, %p.\"", 0, nh_quest_bindings_394, 9},
    {"Mon", "badalign", "synopsis", "nethack.quest.mon.badalign.synopsis", "[You must atone.  Come back when you are worthy of %d.]", 0, nh_quest_bindings_395, 1},
    {"Mon", "badalign", "text", "nethack.quest.mon.badalign.text", "\"This is terrible, %p.  You have deviated from the true path!\nYou know that %d requires the most strident devotion of this\norder.  The %shood must stand for utmost piety.\n\n\"Go from here, atone for your sins against %d.  Return only when\nyou have purified yourself.\"", 0, nh_quest_bindings_396, 3},
    {"Mon", "badlevel", "synopsis", "nethack.quest.mon.badlevel.synopsis", "[You are not ready to face %n.  Come back when you are %Ra.]", 0, nh_quest_bindings_397, 3},
    {"Mon", "badlevel", "text", "nethack.quest.mon.badlevel.text", "\"Alas, %p, it is not yet to be.  A mere %r could never\nwithstand the might of %n.  Go forth, again into the world, and\nreturn when you have attained the post of %R.\"", 0, nh_quest_bindings_398, 4},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_1", "\"Submit to my will, %c, and I shall spare you.\"", 1, nh_quest_bindings_399, 1},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_10", "\"With %o, nothing can stand in my way.\"", 10, nh_quest_bindings_400, 1},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_2", "\"Your puny powers are no match for me, %c.\"", 2, nh_quest_bindings_401, 1},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_3", "\"I shall have you turned into a zombie for my pleasure!\"", 3, NULL, 0},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_4", "\"Despair now, %r.  %d cannot help you.\"", 4, nh_quest_bindings_403, 2},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_5", "\"I shall feast upon your soul for many days, %c.\"", 5, nh_quest_bindings_404, 1},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_6", "\"Your death will be slow and painful.  That I promise!\"", 6, NULL, 0},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_7", "\"You cannot defeat %n, you fool.  I shall kill you now.\"", 7, nh_quest_bindings_406, 1},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_8", "\"Your precious %lt will be my next victim.\"", 8, nh_quest_bindings_407, 2},
    {"Mon", "discourage", "item", "nethack.quest.mon.discourage.item_9", "\"I feel your powers failing you, %r.  You shall die now.\"", 9, nh_quest_bindings_408, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_1", "\"You can prevail, if you rely on %d.\"", 1, nh_quest_bindings_409, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_10", "\"Wear %o.  They will assist you in your efforts.\"", 10, nh_quest_bindings_410, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_2", "\"Remember that %n has great magic at his command.\"", 2, nh_quest_bindings_411, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_3", "\"Be pure, my %S.\"", 3, nh_quest_bindings_412, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_4", "\"Beware, %i is surrounded by hordes of earth elementals.\"", 4, nh_quest_bindings_413, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_5", "\"Remember your studies, and you will prevail!\"", 5, NULL, 0},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_6", "\"Acquire and wear %o if you can.  They will aid you against %n.\"", 6, nh_quest_bindings_415, 2},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_7", "\"Call upon %d when your need is greatest.  You will be answered.\"", 7, nh_quest_bindings_416, 1},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_8", "\"Remember to use the elementals' strength against them!\"", 8, NULL, 0},
    {"Mon", "encourage", "item", "nethack.quest.mon.encourage.item_9", "\"Do not lose faith, %p.  If you do so, %n will grow stronger.\"", 9, nh_quest_bindings_418, 2},
    {"Mon", "firsttime", "synopsis", "nethack.quest.mon.firsttime.synopsis", "[You have reached %H but something is wrong.  %lC needs your aid.]", 0, nh_quest_bindings_419, 3},
    {"Mon", "firsttime", "text", "nethack.quest.mon.firsttime.text", "You find yourself standing in sight of %H.\nSomething is obviously wrong here.  Strange shapes lumber around\noutside %H!\n\nYou realize that %l needs your assistance!", 0, nh_quest_bindings_420, 2},
    {"Mon", "goal_first", "synopsis", "nethack.quest.mon.goal_first.synopsis", "[You are surrounded by brimstone, lava, and elementals.]", 0, NULL, 0},
    {"Mon", "goal_first", "text", "nethack.quest.mon.goal_first.text", "The stench of brimstone is all about you, and the elementals close in\nfrom all sides!\n\nAhead, there is a small clearing amidst the bubbling pits of lava...", 0, NULL, 0},
    {"Mon", "goal_next", "text", "nethack.quest.mon.goal_next.text", "Again, you have invaded %ns domain.", 0, nh_quest_bindings_423, 2},
    {"Mon", "gotit", "synopsis", "nethack.quest.mon.gotit.synopsis", "[You feel the essence of %d and realize that you should take %o to %l.]", 0, nh_quest_bindings_424, 3},
    {"Mon", "gotit", "text", "nethack.quest.mon.gotit.text", "As you pick up %o, you feel the essence of\n%d fill your soul.  You know now why %n stole %oi from\n%H, for with %oi, %ca of %d could\neasily defeat his plans.\n\nYou sense a message from %d.  Though not verbal, you\nget the impression that you must return to %l as soon\nas possible.", 0, nh_quest_bindings_425, 8},
    {"Mon", "guardtalk_after", "item", "nethack.quest.mon.guardtalk_after.item_1", "\"Greetings, honorable %r.  It is good to see you again.\"", 1, nh_quest_bindings_426, 1},
    {"Mon", "guardtalk_after", "item", "nethack.quest.mon.guardtalk_after.item_2", "\"Ah, %p!  Our deepest gratitude for all of your help.\"", 2, nh_quest_bindings_427, 1},
    {"Mon", "guardtalk_after", "item", "nethack.quest.mon.guardtalk_after.item_3", "\"Greetings, %s.  Perhaps you will take some time to meditate with us?\"", 3, nh_quest_bindings_428, 1},
    {"Mon", "guardtalk_after", "item", "nethack.quest.mon.guardtalk_after.item_4", "\"With this test behind you, may %d bring you enlightenment.\"", 4, nh_quest_bindings_429, 1},
    {"Mon", "guardtalk_after", "item", "nethack.quest.mon.guardtalk_after.item_5", "\"May %d be with you, %s.\"", 5, nh_quest_bindings_430, 2},
    {"Mon", "guardtalk_before", "item", "nethack.quest.mon.guardtalk_before.item_1", "\"Greetings, honorable %r.  It is good to see you.\"", 1, nh_quest_bindings_431, 1},
    {"Mon", "guardtalk_before", "item", "nethack.quest.mon.guardtalk_before.item_2", "\"Ah, %p!  Surely you can help us in our hour of need.\"", 2, nh_quest_bindings_432, 1},
    {"Mon", "guardtalk_before", "item", "nethack.quest.mon.guardtalk_before.item_3", "\"Greetings, %s.  %lC has great need of your help.\"", 3, nh_quest_bindings_433, 3},
    {"Mon", "guardtalk_before", "item", "nethack.quest.mon.guardtalk_before.item_4", "\"Alas, it seems as if even %d has deserted us.\"", 4, nh_quest_bindings_434, 1},
    {"Mon", "guardtalk_before", "item", "nethack.quest.mon.guardtalk_before.item_5", "\"May %d be with you, %s.\"", 5, nh_quest_bindings_435, 2},
    {"Mon", "hasamulet", "synopsis", "nethack.quest.mon.hasamulet.synopsis", "[Take the Amulet to the Astral Plane and deliver it to %d.]", 0, nh_quest_bindings_436, 1},
    {"Mon", "hasamulet", "text", "nethack.quest.mon.hasamulet.text", "\"You have prevailed, %p!  %d is surely with you.  Now,\nyou must take the Amulet, and sacrifice it on %ds altar on\nthe Astral Plane.  I suspect that I shall never see you again in this\nlife, but I hope to at %ds feet.\"", 0, nh_quest_bindings_437, 3},
    {"Mon", "killed_nemesis", "synopsis", "nethack.quest.mon.killed_nemesis.synopsis", "[As %n dies, %nh threatens to return.]", 0, nh_quest_bindings_438, 2},
    {"Mon", "killed_nemesis", "text", "nethack.quest.mon.killed_nemesis.text", "%nC gasps:\n\n    \"You have only defeated this mortal body.  Know this: my spirit\n    is strong.  I shall return and reclaim what is mine!\"\n\nWith that, %n expires.", 0, nh_quest_bindings_439, 2},
    {"Mon", "leader_first", "synopsis", "nethack.quest.mon.leader_first.synopsis", "[%lC checks whether you are ready for the great challenge.]", 0, nh_quest_bindings_440, 2},
    {"Mon", "leader_first", "text", "nethack.quest.mon.leader_first.text", "\"Ah, %p, my %S.  You have returned to us at last.\nA great blow has befallen our order; perhaps you can help us.\nFirst, however, I must determine if you are prepared for this\ngreat challenge.\"", 0, nh_quest_bindings_441, 2},
    {"Mon", "leader_last", "synopsis", "nethack.quest.mon.leader_last.synopsis", "[You are a heretic and have failed utterly.]", 0, NULL, 0},
    {"Mon", "leader_last", "text", "nethack.quest.mon.leader_last.text", "\"You are a heretic, %p!  How can you, %ra, deviate so from the\nteachings of %d?  Begone from this temple.  You are no longer\n%sa to this order.  We will pray to %d for other assistance,\nas you have failed us utterly.\"", 0, nh_quest_bindings_443, 6},
    {"Mon", "leader_next", "text", "nethack.quest.mon.leader_next.text", "\"Again, my %S, you stand before me.  Are you ready now to help us?\"", 0, nh_quest_bindings_444, 1},
    {"Mon", "leader_other", "text", "nethack.quest.mon.leader_other.text", "\"Once more, %p, you stand within the sanctum.  Are you ready now?\"", 0, nh_quest_bindings_445, 1},
    {"Mon", "locate_first", "synopsis", "nethack.quest.mon.locate_first.synopsis", "[You have reached %i.  %nC lurks further ahead.]", 0, nh_quest_bindings_446, 3},
    {"Mon", "locate_first", "text", "nethack.quest.mon.locate_first.text", "You remember the descriptions of %i, given\nto you by %l.  It is ahead that you will find\n%n's trail.", 0, nh_quest_bindings_447, 3},
    {"Mon", "locate_next", "text", "nethack.quest.mon.locate_next.text", "Again, you stand before %i.", 0, nh_quest_bindings_448, 1},
    {"Mon", "nemesis_first", "synopsis", "nethack.quest.mon.nemesis_first.synopsis", "[You are no %g.  You shall never regain %o.]", 0, nh_quest_bindings_449, 2},
    {"Mon", "nemesis_first", "text", "nethack.quest.mon.nemesis_first.text", "\"Ah, so %l has sent another %g to retrieve\n%o.\n\n\"No, I see you are no %g.  Perhaps I shall have some fun today\nafter all.  Prepare to die, %r!  You shall never regain\n%o.\"", 0, nh_quest_bindings_450, 4},
    {"Mon", "nemesis_next", "text", "nethack.quest.mon.nemesis_next.text", "\"So, %r.  Again you challenge me.\"", 0, nh_quest_bindings_451, 1},
    {"Mon", "nemesis_other", "text", "nethack.quest.mon.nemesis_other.text", "\"Die now, %r.  %d has no power here to aid you.\"", 0, nh_quest_bindings_452, 2},
    {"Mon", "nemesis_wantsit", "text", "nethack.quest.mon.nemesis_wantsit.text", "\"You shall die, %r, and I will have %o back.\"", 0, nh_quest_bindings_453, 2},
    {"Mon", "nexttime", "text", "nethack.quest.mon.nexttime.text", "Once again, you stand before %H.", 0, nh_quest_bindings_454, 1},
    {"Mon", "offeredit", "synopsis", "nethack.quest.mon.offeredit.synopsis", "[Keep %o.  %oH will help you recover the Amulet of Yendor.]", 0, nh_quest_bindings_455, 2},
    {"Mon", "offeredit", "text", "nethack.quest.mon.offeredit.text", "\"You have returned, %p.  And with %o, I see.\nCongratulations.\n\n\"I have been in meditation, and have received direction from\na minion of %d.  %d commands that you retain\n%o.  With %oi, you must recover the Amulet\nof Yendor.\n\n\"Go forth, and let %d guide your steps.\"", 0, nh_quest_bindings_456, 4},
    {"Mon", "offeredit2", "synopsis", "nethack.quest.mon.offeredit2.synopsis", "[Keep %o and return to %Z to search for the Amulet.]", 0, nh_quest_bindings_457, 2},
    {"Mon", "offeredit2", "text", "nethack.quest.mon.offeredit2.text", "%lC studies %o for a moment,\nthen returns his gaze to you.\n\n\"%oC must remain with you.  Use %oi\nas you resume your search for the Amulet.\n%Z await your return through the magic portal\nthat brought you here.\"", 0, nh_quest_bindings_458, 6},
    {"Mon", "othertime", "text", "nethack.quest.mon.othertime.text", "Again you face %H.  Your intuition hints that this\nmay be the final time you come here.", 0, nh_quest_bindings_459, 1},
    {"Mon", "posthanks", "text", "nethack.quest.mon.posthanks.text", "\"Welcome back, %p.  How is your quest for the Amulet going?\"", 0, nh_quest_bindings_460, 1},
    {"Pri", "assignquest", "synopsis", "nethack.quest.pri.assignquest.synopsis", "[%nC invaded %H and captured %o.  Defeat %ni and retrieve %oh.]", 0, nh_quest_bindings_461, 6},
    {"Pri", "assignquest", "text", "nethack.quest.pri.assignquest.text", "\"Yes, %p.  You are truly ready now.  Attend to me and I shall\ntell you of what has transpired:\n\n\"At one of the Great Festivals a short time ago, %n and a legion\nof undead invaded %H.  Many %gP were killed, including\nthe one carrying %o.\n\n\"As a final act of vengefulness, %n desecrated the altar here.\nWithout it, we could not mount a counter-attack.  Now, there are\nbarely enough %gP left to keep the undead at bay.\n\n\"We need you to find %i, then, from there, travel\nto %ns lair.  If you can manage to defeat %n and return\n%o here, we can then drive off the legions of\nundead that befoul the land.\n\n\"Go with %d as your guide, %p.\"", 0, nh_quest_bindings_462, 9},
    {"Pri", "badalign", "synopsis", "nethack.quest.pri.badalign.synopsis", "[You have deviated from the path.  Return when you have purified yourself.]", 0, NULL, 0},
    {"Pri", "badalign", "text", "nethack.quest.pri.badalign.text", "\"This is terrible, %p.  You have deviated from the true path!\nYou know that %d requires the most strident devotion of this\norder.  The %shood must stand for utmost piety.\n\n\"Go from here, atone for your sins against %d.  Return only when\nyou have purified yourself.\"", 0, nh_quest_bindings_464, 3},
    {"Pri", "badlevel", "synopsis", "nethack.quest.pri.badlevel.synopsis", "[%rA cannot withstand %n.  Come back when you are %Ra.]", 0, nh_quest_bindings_465, 5},
    {"Pri", "badlevel", "text", "nethack.quest.pri.badlevel.text", "\"Alas, %p, it is not yet to be.  A mere %r could never\nwithstand the might of %n.  Go forth, again into the world, and return\nwhen you have attained the post of %R.\"", 0, nh_quest_bindings_466, 4},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_1", "\"Submit to my will, %c, and I shall spare you.\"", 1, nh_quest_bindings_467, 1},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_10", "\"With %o, nothing can stand in my way.\"", 10, nh_quest_bindings_468, 1},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_2", "\"Your puny powers are no match for me, %c.\"", 2, nh_quest_bindings_469, 1},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_3", "\"I shall have you turned into a zombie for my pleasure!\"", 3, NULL, 0},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_4", "\"Despair now, %r.  %d cannot help you.\"", 4, nh_quest_bindings_471, 2},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_5", "\"I shall feast upon your soul for many days, %c.\"", 5, nh_quest_bindings_472, 1},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_6", "\"Your death will be slow and painful.  That I promise!\"", 6, NULL, 0},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_7", "\"You cannot defeat %n, you fool.  I shall kill you now.\"", 7, nh_quest_bindings_474, 1},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_8", "\"Your precious %lt will be my next victim.\"", 8, nh_quest_bindings_475, 2},
    {"Pri", "discourage", "item", "nethack.quest.pri.discourage.item_9", "\"I feel your powers failing you, %r.  You shall die now.\"", 9, nh_quest_bindings_476, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_1", "\"You can prevail, if you rely on %d.\"", 1, nh_quest_bindings_477, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_10", "\"Wear %o.  It will assist you against the undead.\"", 10, nh_quest_bindings_478, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_2", "\"Remember that %n has great magic at his command.\"", 2, nh_quest_bindings_479, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_3", "\"Be pure, my %S.\"", 3, nh_quest_bindings_480, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_4", "\"Beware, %i is surrounded by a great graveyard.\"", 4, nh_quest_bindings_481, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_5", "\"You may be able to affect %n with magical cold.\"", 5, nh_quest_bindings_482, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_6", "\"Acquire and wear %o if you can.  It will aid you against %n.\"", 6, nh_quest_bindings_483, 2},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_7", "\"Call upon %d when your need is greatest.  You will be answered.\"", 7, nh_quest_bindings_484, 1},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_8", "\"The undead legions are weakest during the daylight hours.\"", 8, NULL, 0},
    {"Pri", "encourage", "item", "nethack.quest.pri.encourage.item_9", "\"Do not lose faith, %p.  If you do so, %n will grow stronger.\"", 9, nh_quest_bindings_486, 2},
    {"Pri", "firsttime", "synopsis", "nethack.quest.pri.firsttime.synopsis", "[You are at %H; the doors are closed.  %lC needs your help!]", 0, nh_quest_bindings_487, 3},
    {"Pri", "firsttime", "text", "nethack.quest.pri.firsttime.text", "You find yourself standing in sight of %H.  Something\nis obviously wrong here.  The doors to %H, which usually\nstand open, are closed.  Strange human shapes shamble around\noutside.\n\nYou realize that %l needs your assistance!", 0, nh_quest_bindings_488, 2},
    {"Pri", "goal_first", "synopsis", "nethack.quest.pri.goal_first.synopsis", "[The stench of brimstone surrounds you, the shrieks and moans are endless.]", 0, NULL, 0},
    {"Pri", "goal_first", "text", "nethack.quest.pri.goal_first.text", "The stench of brimstone is all about you, and the shrieks and moans\nof tortured souls assault your psyche.\n\nAhead, there is a small clearing amidst the bubbling pits of lava...", 0, NULL, 0},
    {"Pri", "goal_next", "text", "nethack.quest.pri.goal_next.text", "Again, you have invaded %ns domain.", 0, nh_quest_bindings_491, 2},
    {"Pri", "gotit", "synopsis", "nethack.quest.pri.gotit.synopsis", "[You feel %d as you pick up %o; return %oh to %l.]", 0, nh_quest_bindings_492, 4},
    {"Pri", "gotit", "text", "nethack.quest.pri.gotit.text", "As you pick up %o, you feel the essence of\n%d fill your soul.  You know now why %n stole it from\n%H, for with it, %ca of %d could\neasily defeat his plans.\n\nYou sense a message from %d.  Though not verbal, you\nget the impression that you must return to %l as soon\nas possible.", 0, nh_quest_bindings_493, 7},
    {"Pri", "guardtalk_after", "item", "nethack.quest.pri.guardtalk_after.item_1", "\"Greetings, %r.  It is good to see you again.\"", 1, nh_quest_bindings_494, 1},
    {"Pri", "guardtalk_after", "item", "nethack.quest.pri.guardtalk_after.item_2", "\"Ah, %p!  Our deepest gratitude for all of your help.\"", 2, nh_quest_bindings_495, 1},
    {"Pri", "guardtalk_after", "item", "nethack.quest.pri.guardtalk_after.item_3", "\"Welcome back, %s!  With %o, no undead can stand against us.\"", 3, nh_quest_bindings_496, 2},
    {"Pri", "guardtalk_after", "item", "nethack.quest.pri.guardtalk_after.item_4", "\"Praise be to %d, for delivering us from %n.\"", 4, nh_quest_bindings_497, 2},
    {"Pri", "guardtalk_after", "item", "nethack.quest.pri.guardtalk_after.item_5", "\"May %d be with you, %s.\"", 5, nh_quest_bindings_498, 2},
    {"Pri", "guardtalk_before", "item", "nethack.quest.pri.guardtalk_before.item_1", "\"Greetings, honored %r.  It is good to see you.\"", 1, nh_quest_bindings_499, 1},
    {"Pri", "guardtalk_before", "item", "nethack.quest.pri.guardtalk_before.item_2", "\"Ah, %p!  Surely you can help us in our hour of need.\"", 2, nh_quest_bindings_500, 1},
    {"Pri", "guardtalk_before", "item", "nethack.quest.pri.guardtalk_before.item_3", "\"Greetings, %s.  %lC has great need of your help.\"", 3, nh_quest_bindings_501, 3},
    {"Pri", "guardtalk_before", "item", "nethack.quest.pri.guardtalk_before.item_4", "\"Alas, it seems as if even %d has deserted us.\"", 4, nh_quest_bindings_502, 1},
    {"Pri", "guardtalk_before", "item", "nethack.quest.pri.guardtalk_before.item_5", "\"May %d be with you, %s.\"", 5, nh_quest_bindings_503, 2},
    {"Pri", "hasamulet", "synopsis", "nethack.quest.pri.hasamulet.synopsis", "[Take the Amulet to the Astral Plane and offer it on %ds altar.]", 0, nh_quest_bindings_504, 2},
    {"Pri", "hasamulet", "text", "nethack.quest.pri.hasamulet.text", "\"You have prevailed, %p!  %d is surely with you.  Now,\nyou must take the amulet, and sacrifice it on %ds altar on\nthe Astral Plane.  I suspect that I shall never see you again in this\nlife, but I hope to at %ds feet.\"", 0, nh_quest_bindings_505, 3},
    {"Pri", "killed_nemesis", "synopsis", "nethack.quest.pri.killed_nemesis.synopsis", "[%nC dies.  Moloch is aware of you and angry at %n.]", 0, nh_quest_bindings_506, 2},
    {"Pri", "killed_nemesis", "text", "nethack.quest.pri.killed_nemesis.text", "You feel a wrenching shift in the ether as %ns body dissolves\ninto a cloud of noxious gas.\n\nSuddenly, a voice booms out:\n\n    \"Thou hast defeated the least of my minions, %r.\n    Know now that Moloch is aware of thy presence.\n    As for thee, %n, I shall deal with thy failure\n    at my leisure.\"\n\nYou then hear the voice of %n, screaming in terror...", 0, nh_quest_bindings_507, 3},
    {"Pri", "leader_first", "synopsis", "nethack.quest.pri.leader_first.synopsis", "[You have returned and we need your help.  Are you ready?]", 0, NULL, 0},
    {"Pri", "leader_first", "text", "nethack.quest.pri.leader_first.text", "\"Ah, %p, my %S.  You have returned to us at last.\nA great blow has befallen our order; perhaps you can help us.\nFirst, however, I must determine if you are prepared for this\ngreat challenge.\"", 0, nh_quest_bindings_509, 2},
    {"Pri", "leader_last", "synopsis", "nethack.quest.pri.leader_last.synopsis", "[You are a heretic who has deviated from the teachings of %d.]", 0, nh_quest_bindings_510, 1},
    {"Pri", "leader_last", "text", "nethack.quest.pri.leader_last.text", "\"You are a heretic, %p!  How can you, %ra, deviate so from the\nteachings of %d?  Begone from this temple.  You are no longer\n%sa to this order.  We will pray to %d for other assistance,\nas you have failed us utterly.\"", 0, nh_quest_bindings_511, 6},
    {"Pri", "leader_next", "text", "nethack.quest.pri.leader_next.text", "\"Again, my %S, you stand before me.  Are you ready now to help us?\"", 0, nh_quest_bindings_512, 1},
    {"Pri", "leader_other", "text", "nethack.quest.pri.leader_other.text", "\"Once more, %p, you stand within the sanctum.  Are you ready now?\"", 0, nh_quest_bindings_513, 1},
    {"Pri", "locate_first", "synopsis", "nethack.quest.pri.locate_first.synopsis", "[You have found %i.  The trail to %n lies ahead.]", 0, nh_quest_bindings_514, 2},
    {"Pri", "locate_first", "text", "nethack.quest.pri.locate_first.text", "You stand facing a large graveyard.  The sky above is filled with clouds\nthat seem to get thicker closer to the center.  You sense the presence of\nundead in larger numbers than you have ever encountered before.\n\nYou remember the descriptions of %i, given to you by\n%l.  It is ahead that you will find %ns trail.", 0, nh_quest_bindings_515, 4},
    {"Pri", "locate_next", "text", "nethack.quest.pri.locate_next.text", "Again, you stand before %i.", 0, nh_quest_bindings_516, 1},
    {"Pri", "nemesis_first", "synopsis", "nethack.quest.pri.nemesis_first.synopsis", "[%lC has sent you, but you are no %gC.  I shall destroy you.]", 0, nh_quest_bindings_517, 4},
    {"Pri", "nemesis_first", "text", "nethack.quest.pri.nemesis_first.text", "\"Ah, so %l has sent another %gC to retrieve\n%o.\n\n\"No, I see you are no %gC.  Perhaps I shall have some fun today\nafter all.  Prepare to die, %r!  You shall never regain\n%o.\"", 0, nh_quest_bindings_518, 5},
    {"Pri", "nemesis_next", "text", "nethack.quest.pri.nemesis_next.text", "\"So, %r.  Again you challenge me.\"", 0, nh_quest_bindings_519, 1},
    {"Pri", "nemesis_other", "text", "nethack.quest.pri.nemesis_other.text", "\"Die now, %r.  %d has no power here to aid you.\"", 0, nh_quest_bindings_520, 2},
    {"Pri", "nemesis_wantsit", "text", "nethack.quest.pri.nemesis_wantsit.text", "\"You shall die, %r, and I will have %o back.\"", 0, nh_quest_bindings_521, 2},
    {"Pri", "nexttime", "text", "nethack.quest.pri.nexttime.text", "Once again, you stand before %H.", 0, nh_quest_bindings_522, 1},
    {"Pri", "offeredit", "synopsis", "nethack.quest.pri.offeredit.synopsis", "[Congratulations, %p.  Keep %o; go and recover the Amulet.]", 0, nh_quest_bindings_523, 2},
    {"Pri", "offeredit", "text", "nethack.quest.pri.offeredit.text", "\"You have returned, %p.  And with %o, I see.\nCongratulations.\n\n\"I have been in meditation, and have received direction from\na minion of %d.  %d commands that you retain\n%o.  With it, you must recover the Amulet\nof Yendor.\n\n\"Go forth, and let %d guide your steps.\"", 0, nh_quest_bindings_524, 3},
    {"Pri", "offeredit2", "synopsis", "nethack.quest.pri.offeredit2.synopsis", "[%oC is yours now.  Return to %Z and find the Amulet.]", 0, nh_quest_bindings_525, 3},
    {"Pri", "offeredit2", "text", "nethack.quest.pri.offeredit2.text", "%lC reiterates that %o is yours now.\n\n\"The time has come to resume your search for the Amulet.\n%Z await your return through the magic portal\nthat brought you here.\"", 0, nh_quest_bindings_526, 4},
    {"Pri", "othertime", "text", "nethack.quest.pri.othertime.text", "Again you face %H.  Your intuition hints that this may be\nthe final time you come here.", 0, nh_quest_bindings_527, 1},
    {"Pri", "posthanks", "text", "nethack.quest.pri.posthanks.text", "\"Welcome back, %p.  How is your quest for the Amulet going?\"", 0, nh_quest_bindings_528, 1},
    {"Ran", "assignquest", "synopsis", "nethack.quest.ran.assignquest.synopsis", "[%nC has stolen %o.  Infiltrate %i and retrieve %oh for us.]", 0, nh_quest_bindings_529, 5},
    {"Ran", "assignquest", "text", "nethack.quest.ran.assignquest.text", "\"You are indeed ready, %p.  I shall tell you what has transpired,\nand why we so desperately need your help:\n\n\"A short time ago, the mountain centaurs to the east invaded\nand enslaved the plains centaurs in this area.  The local\nleader is now only a figurehead, and serves %n.\n\n\"During our last gathering of worship here, we were beset by hordes of\nhostile centaurs, as you witnessed.  In the first onslaught a group,\nheaded by %n %niself, managed to breach the grove and steal\n%o.\n\n\"Since then, we have been besieged.  We do not know how much longer\nwe will be able to maintain our magical barriers.\n\n\"If we are to survive, you, %p, must infiltrate\n%i.  There, you will find a pathway down, to the\nunderground cavern of %n.  He has always coveted\n%o, and will surely keep it.\n\n\"Recover %o for us, %p!  Only then will %d be safe.\"", 0, nh_quest_bindings_530, 6},
    {"Ran", "badalign", "synopsis", "nethack.quest.ran.badalign.synopsis", "[You are not sufficiently %a.  Come back when you have purified yourself.]", 0, nh_quest_bindings_531, 1},
    {"Ran", "badalign", "text", "nethack.quest.ran.badalign.text", "\"You have strayed, %p!  You know that %d requires that\nwe maintain a pure devotion to things %a!\n\n\"You must go from us.  Return when you have purified yourself.\"", 0, nh_quest_bindings_532, 3},
    {"Ran", "badlevel", "synopsis", "nethack.quest.ran.badlevel.synopsis", "[You are too inexperienced.  Come back when you are %Ra.]", 0, nh_quest_bindings_533, 2},
    {"Ran", "badlevel", "text", "nethack.quest.ran.badlevel.text", "\"%p, you are yet too inexperienced to withstand the demands of that\nwhich we need you to do.  %RA might just be able to do this thing.\n\n\"Return to us when you have learned more, my %S.\"", 0, nh_quest_bindings_534, 4},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_1", "\"Your %d is nothing, %c.  You are mine now!\"", 1, nh_quest_bindings_535, 2},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_10", "\"You weaken, %c.  I shall kill you now.\"", 10, nh_quest_bindings_536, 1},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_2", "\"Run away little %c!  You can never hope to defeat %n!\"", 2, nh_quest_bindings_537, 2},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_3", "\"My servants will rip you to shreds!\"", 3, NULL, 0},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_4", "\"I shall display your head as a trophy.  What do you think about that wall?\"", 4, NULL, 0},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_5", "\"I shall break your %ls grove, and destroy all the %gP!\"", 5, nh_quest_bindings_540, 4},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_6", "\"%d has abandoned you, %c.  You are doomed.\"", 6, nh_quest_bindings_541, 2},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_7", "\"%rA?  %lC sends a mere %r against me?  Hah!\"", 7, nh_quest_bindings_542, 4},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_8", "\"%lC has failed, %c.  %oC will never leave here.\"", 8, nh_quest_bindings_543, 5},
    {"Ran", "discourage", "item", "nethack.quest.ran.discourage.item_9", "\"You really think you can defeat me, eh %c?  You are wrong!\"", 9, nh_quest_bindings_544, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_1", "\"It is rumored that the Forest and Mountain Centaurs have resolved their ancient feud and now band together against us.\"", 1, NULL, 0},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_10", "\"You can triumph, %p, if you trust in %d.\"", 10, nh_quest_bindings_546, 2},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_2", "\"%nC is strong, and very smart.\"", 2, nh_quest_bindings_547, 2},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_3", "\"Use %o, when you find it.  It will help you survive to reach us.\"", 3, nh_quest_bindings_548, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_4", "\"Remember, let %d be your guide.\"", 4, nh_quest_bindings_549, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_5", "\"Call upon %d when you face %n. The very act of doing so will infuriate him, and give you advantage.\"", 5, nh_quest_bindings_550, 2},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_6", "\"%n and his kind have always hated us.\"", 6, nh_quest_bindings_551, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_7", "\"We cannot hold the grove much longer, %p.  Hurry!\"", 7, nh_quest_bindings_552, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_8", "\"To infiltrate %i, you must be very stealthy.\"", 8, nh_quest_bindings_553, 1},
    {"Ran", "encourage", "item", "nethack.quest.ran.encourage.item_9", "\"Remember that %n is a braggart.  Trust not what he says.\"", 9, nh_quest_bindings_554, 1},
    {"Ran", "firsttime", "synopsis", "nethack.quest.ran.firsttime.synopsis", "[The ancient forest grove is surrounded by centaurs.]", 0, NULL, 0},
    {"Ran", "firsttime", "text", "nethack.quest.ran.firsttime.text", "You arrive in familiar surroundings.  In the distance, you %x the\nancient forest grove, the place of worship to %d.\n\nSomething is wrong, though.  Surrounding the grove are centaurs!\nAnd they've noticed you!", 0, nh_quest_bindings_556, 2},
    {"Ran", "goal_first", "synopsis", "nethack.quest.ran.goal_first.synopsis", "[You descend into a subterranean complex.  Hooves clatter in the distance.]", 0, NULL, 0},
    {"Ran", "goal_first", "text", "nethack.quest.ran.goal_first.text", "You descend into a weird place, in which roughly cut cave-like walls\njoin with smooth, finished ones, as if someone was in the midst of\nfinishing off the construction of a subterranean complex.\n\nOff in the distance, you hear a sound like the clattering of many\nhooves on rock.", 0, NULL, 0},
    {"Ran", "goal_next", "text", "nethack.quest.ran.goal_next.text", "Once again, you enter the distorted castle of %n.", 0, nh_quest_bindings_559, 1},
    {"Ran", "gotit", "synopsis", "nethack.quest.ran.gotit.synopsis", "[You pick up %o and feel power.  It's time to return %oh to %l.]", 0, nh_quest_bindings_560, 3},
    {"Ran", "gotit", "text", "nethack.quest.ran.gotit.text", "As you pick up %o, it seems to glow, and a warmth\nfills you completely.  You realize that its power is what has protected\nyour %sp against their enemies for so long.\n\nYou must now return it to %l without delay -- their lives depend\non your speed.", 0, nh_quest_bindings_561, 4},
    {"Ran", "guardtalk_after", "item", "nethack.quest.ran.guardtalk_after.item_1", "\"%pC!  I have not seen you in many moons.  How do you fare?\"", 1, nh_quest_bindings_562, 2},
    {"Ran", "guardtalk_after", "item", "nethack.quest.ran.guardtalk_after.item_2", "\"Birdsong has returned to the grove, surely this means you have defeated %n.\"", 2, nh_quest_bindings_563, 1},
    {"Ran", "guardtalk_after", "item", "nethack.quest.ran.guardtalk_after.item_3", "\"%lC seems to have regained some of his strength.\"", 3, nh_quest_bindings_564, 2},
    {"Ran", "guardtalk_after", "item", "nethack.quest.ran.guardtalk_after.item_4", "\"So, tell us how you entered %i, in case some new evil arises there.\"", 4, nh_quest_bindings_565, 1},
    {"Ran", "guardtalk_after", "item", "nethack.quest.ran.guardtalk_after.item_5", "\"Is that truly %o that I see you carrying?\"", 5, nh_quest_bindings_566, 1},
    {"Ran", "guardtalk_before", "item", "nethack.quest.ran.guardtalk_before.item_1", "\"%pC!  I have not seen you in many moons.  How do you fare?\"", 1, nh_quest_bindings_567, 2},
    {"Ran", "guardtalk_before", "item", "nethack.quest.ran.guardtalk_before.item_2", "\"%nC continues to threaten the grove.  But we hold fast.\"", 2, nh_quest_bindings_568, 2},
    {"Ran", "guardtalk_before", "item", "nethack.quest.ran.guardtalk_before.item_3", "\"%lC is growing weak.  The magic required to defend the grove drains us.\"", 3, nh_quest_bindings_569, 2},
    {"Ran", "guardtalk_before", "item", "nethack.quest.ran.guardtalk_before.item_4", "\"Remember %i is hard to enter.  Beware the distraction of leatherwings.\"", 4, nh_quest_bindings_570, 1},
    {"Ran", "guardtalk_before", "item", "nethack.quest.ran.guardtalk_before.item_5", "\"We must regain %o.  Without it we will be overrun.\"", 5, nh_quest_bindings_571, 1},
    {"Ran", "hasamulet", "synopsis", "nethack.quest.ran.hasamulet.synopsis", "[You have the Amulet!  Take it to the Astral Plane and offer it to %d.]", 0, nh_quest_bindings_572, 1},
    {"Ran", "hasamulet", "text", "nethack.quest.ran.hasamulet.text", "\"You have it!  You have recovered the Amulet of Yendor!\nNow attend to me, %p, and I will tell you what must be done:\n\n\"The Amulet has within it magic, the capability to transport you to\nthe Astral Plane, where the primary circle of %d resides.\n\n\"To activate this magic, you must travel upwards as far as you can.\nWhen you reach the temple, sacrifice the Amulet to %d.\n\n\"Thus will you fulfill your destiny.\"", 0, nh_quest_bindings_573, 2},
    {"Ran", "killed_nemesis", "synopsis", "nethack.quest.ran.killed_nemesis.synopsis", "[%nC curses you as %nh dies.]", 0, nh_quest_bindings_574, 3},
    {"Ran", "killed_nemesis", "text", "nethack.quest.ran.killed_nemesis.text", "%nC collapses to the ground, cursing you and %l, then says:\n\n    \"You have defeated me, %r!  But I curse you one final time, with\n    my dying breath!  You shall die before you leave my castle!\"", 0, nh_quest_bindings_575, 4},
    {"Ran", "leader_first", "synopsis", "nethack.quest.ran.leader_first.synopsis", "[You have returned, %p.  We need your help.  Are you ready?]", 0, nh_quest_bindings_576, 1},
    {"Ran", "leader_first", "text", "nethack.quest.ran.leader_first.text", "\"%pC!  You have returned!  Thank %d.\n\n\"We have great need of you.  But first, I must see if you have the\nrequired abilities to take on this responsibility.\"", 0, nh_quest_bindings_577, 3},
    {"Ran", "leader_last", "synopsis", "nethack.quest.ran.leader_last.synopsis", "[You are not sufficiently %a.  We renounce your %shood.]", 0, nh_quest_bindings_578, 2},
    {"Ran", "leader_last", "text", "nethack.quest.ran.leader_last.text", "\"%pC!  You have doomed us all.  You fairly radiate %L influences\nand weaken the power we have raised in this grove as a result!\n\n\"Begone!  We renounce your %shood with us!  You are an outcast now!\"", 0, nh_quest_bindings_579, 4},
    {"Ran", "leader_next", "text", "nethack.quest.ran.leader_next.text", "\"Once again, %p, you stand in our midst.  Are you ready now?\"", 0, nh_quest_bindings_580, 1},
    {"Ran", "leader_other", "text", "nethack.quest.ran.leader_other.text", "\"Ah, you are here again, %p.  Allow me to determine your readiness...\"", 0, nh_quest_bindings_581, 1},
    {"Ran", "locate_first", "synopsis", "nethack.quest.ran.locate_first.synopsis", "[This is %i.  There are bats nearby.  Beware the wumpus!]", 0, nh_quest_bindings_582, 1},
    {"Ran", "locate_first", "text", "nethack.quest.ran.locate_first.text", "This must be %i.\n\nYou are in a cave built of many different rooms, all interconnected\nby tunnels.  Your quest is to find and shoot the evil wumpus that\nresides elsewhere in the cave without running into any bottomless\npits or using up your limited supply of arrows.  Good luck.\n\nYou are in room 9 of the cave.  There are tunnels to rooms\n5, 8, and 10.\n*rustle* *rustle* (must be bats nearby.)\n*sniff* (I can smell the evil wumpus nearby!)", 0, nh_quest_bindings_583, 1},
    {"Ran", "locate_next", "synopsis", "nethack.quest.ran.locate_next.synopsis", "[You are in %i.  There are pits.  There are bats nearby.]", 0, nh_quest_bindings_584, 1},
    {"Ran", "locate_next", "text", "nethack.quest.ran.locate_next.text", "Once again, you descend into %i.\n\n*whoosh* (I feel a draft from some pits.)\n*rustle* *rustle* (must be bats nearby.)", 0, nh_quest_bindings_585, 1},
    {"Ran", "nemesis_first", "synopsis", "nethack.quest.ran.nemesis_first.synopsis", "[You have come to recover %o, but I shall keep %oh and you shall die.]", 0, nh_quest_bindings_586, 2},
    {"Ran", "nemesis_first", "text", "nethack.quest.ran.nemesis_first.text", "\"So, %c.  %lC has sent you to recover %o.\n\n\"Well, I shall keep that bauble.  It pleases me.  You, %c, shall die.\"", 0, nh_quest_bindings_587, 4},
    {"Ran", "nemesis_next", "text", "nethack.quest.ran.nemesis_next.text", "\"Back again, eh?  Well, a mere %r is no threat to me!  Die, %c!\"", 0, nh_quest_bindings_588, 2},
    {"Ran", "nemesis_other", "text", "nethack.quest.ran.nemesis_other.text", "\"You haven't learned your lesson, %c.  You can't kill me!  You shall die now.\"", 0, nh_quest_bindings_589, 1},
    {"Ran", "nemesis_wantsit", "text", "nethack.quest.ran.nemesis_wantsit.text", "\"I shall have %o from you, %r.  Then I shall\nkill you.\"", 0, nh_quest_bindings_590, 2},
    {"Ran", "nexttime", "text", "nethack.quest.ran.nexttime.text", "Once again, you stand before %H.", 0, nh_quest_bindings_591, 1},
    {"Ran", "offeredit", "synopsis", "nethack.quest.ran.offeredit.synopsis", "[You have succeeded.  Take %o with you as you go to find the Amulet.]", 0, nh_quest_bindings_592, 1},
    {"Ran", "offeredit", "text", "nethack.quest.ran.offeredit.text", "\"%pC!  You have succeeded!  I feared it was not possible!\n\n\"You have returned with %o!\n\n\"I fear, now, that the Centaurs will regroup and plot yet another raid.\nThis will take some time, but if you can recover the Amulet of Yendor\nfor %d before that happens, we will be eternally safe.\n\n\"Take %o with you.  It will aid in your quest for\nthe Amulet.\"", 0, nh_quest_bindings_593, 4},
    {"Ran", "offeredit2", "synopsis", "nethack.quest.ran.offeredit2.synopsis", "[You are the keeper of %o now.  Go and find the Amulet.]", 0, nh_quest_bindings_594, 1},
    {"Ran", "offeredit2", "text", "nethack.quest.ran.offeredit2.text", "%l flexes %o reverently.\n\n\"With this wondrous bow, one need never run out of arrows.\nYou are its keeper now, and the time has come to resume your\nsearch for the Amulet.  %Z await your return\nthrough the magic portal that brought you here.\"", 0, nh_quest_bindings_595, 3},
    {"Ran", "othertime", "text", "nethack.quest.ran.othertime.text", "You have the oddest feeling that this may be the last time you\nare to enter %H.", 0, nh_quest_bindings_596, 1},
    {"Ran", "posthanks", "text", "nethack.quest.ran.posthanks.text", "\"Welcome, %p.  How have you fared on your quest for the Amulet\nof Yendor?\"", 0, nh_quest_bindings_597, 1},
    {"Rog", "assignquest", "synopsis", "nethack.quest.rog.assignquest.synopsis", "[Get %o from %n and bring it to %l.]", 0, nh_quest_bindings_598, 3},
    {"Rog", "assignquest", "text", "nethack.quest.rog.assignquest.text", "\"Will everyone not going to retrieve %o from that\njerk, %n, take one step backwards.  Good choice,\n%p, because I was going to send you anyway.  My other %gp\nare too valuable to me.\n\n\"Here's the deal.  I want %o, %n\nhas %o.  You are going to get %o\nand bring it back to me.  So simple an assignment even you can understand\nit.\"", 0, nh_quest_bindings_599, 5},
    {"Rog", "badalign", "synopsis", "nethack.quest.rog.badalign.synopsis", "[Come back when you are really %a.]", 0, nh_quest_bindings_600, 1},
    {"Rog", "badalign", "text", "nethack.quest.rog.badalign.text", "\"Maybe I should chain you to my perch here for a while.  Perhaps watching\nreal %a men at work will bring some sense back to you.  I don't\nthink I could stand the sight of you for that long though.  Come back\nwhen you can be trusted to act properly.\"", 0, nh_quest_bindings_601, 1},
    {"Rog", "badlevel", "synopsis", "nethack.quest.rog.badlevel.synopsis", "[%rA is not adequately trained to handle this job.]", 0, nh_quest_bindings_602, 2},
    {"Rog", "badlevel", "text", "nethack.quest.rog.badlevel.text", "\"In the time that you've been gone you've only been able to master the\narts of %ra?  I've trained ten times again as many %Rp\nin that time.  Maybe I should send one of them, no?  Where would that\nleave you, %p?  Oh yeah, I remember, I was going to kill you!\"", 0, nh_quest_bindings_603, 5},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_1", "\"May I suggest a compromise.  Are you interested in gold or gems?\"", 1, NULL, 0},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_10", "\"I can reunite you with the Twain.  Oh, the stories you can swap.\"", 10, NULL, 0},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_2", "\"Please don't force me to kill you.\"", 2, NULL, 0},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_3", "\"Grim times are upon us all.  Will you not see reason?\"", 3, NULL, 0},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_4", "\"I knew %l, and you're no %lt, thankfully.\"", 4, nh_quest_bindings_608, 2},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_5", "\"It is a shame that we are not meeting under more pleasant circumstances.\"", 5, NULL, 0},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_6", "\"I was once like you are now, %p.  Believe in me -- our way is better.\"", 6, nh_quest_bindings_610, 1},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_7", "\"Stay with me, and I will make you %os guardian.\"", 7, nh_quest_bindings_611, 2},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_8", "\"When you return, with or without %o, %l will have you killed.\"", 8, nh_quest_bindings_612, 2},
    {"Rog", "discourage", "item", "nethack.quest.rog.discourage.item_9", "\"Do not be fooled; I am prepared to kill to defend %o.\"", 9, nh_quest_bindings_613, 1},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_1", "\"You don't seem to understand, %o isn't here so neither should you be!\"", 1, nh_quest_bindings_614, 1},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_10", "\"You know, %o isn't going to come when you whistle.  You must get it yourself.\"", 10, nh_quest_bindings_615, 1},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_2", "\"May %d curse you with lead fingers.  Get going!\"", 2, nh_quest_bindings_616, 1},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_3", "\"We don't have all year.  GET GOING!\"", 3, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_4", "\"How would you like a scar necklace?  I'm just the jeweler to do it!\"", 4, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_5", "\"Lazy S.O.B.  Maybe I should call up someone else...\"", 5, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_6", "\"Maybe I should open your skull and see if my instructions are inside?\"", 6, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_7", "\"This is not a task you can complete in the afterlife, you know.\"", 7, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_8", "\"Inside every living person is a dead person trying to get out, and I have your key!\"", 8, NULL, 0},
    {"Rog", "encourage", "item", "nethack.quest.rog.encourage.item_9", "\"We're almost out of hell-hound chow, so why don't you just get moving!\"", 9, NULL, 0},
    {"Rog", "firsttime", "synopsis", "nethack.quest.rog.firsttime.synopsis", "[You are in Ransmannsby, where you trained.  Find %l.]", 0, nh_quest_bindings_624, 1},
    {"Rog", "firsttime", "text", "nethack.quest.rog.firsttime.text", "Unexpectedly, you find yourself back in Ransmannsby, where you trained to\nbe a thief.  Quickly you make the guild sign, hoping that you AND word\nof your arrival reach %ls den.", 0, nh_quest_bindings_625, 2},
    {"Rog", "goal_first", "synopsis", "nethack.quest.rog.goal_first.synopsis", "[You sense %o.]", 0, nh_quest_bindings_626, 1},
    {"Rog", "goal_first", "text", "nethack.quest.rog.goal_first.text", "You feel a great swelling up of courage, sensing the presence of\n%o.  Or is it fear?", 0, nh_quest_bindings_627, 1},
    {"Rog", "goal_next", "text", "nethack.quest.rog.goal_next.text", "The hairs on the back of your neck whisper -- it's fear.", 0, NULL, 0},
    {"Rog", "gotit", "synopsis", "nethack.quest.rog.gotit.synopsis", "[You pick up %o and know that %l should not have it.]", 0, nh_quest_bindings_629, 2},
    {"Rog", "gotit", "text", "nethack.quest.rog.gotit.text", "As you pick up %o, the hairs on the back of your\nneck fall out.  At once you realize why %n was\nwilling to die to keep it out of %ls hands.  Somehow\nyou know that you must do likewise.", 0, nh_quest_bindings_630, 4},
    {"Rog", "guardtalk_after", "item", "nethack.quest.rog.guardtalk_after.item_1", "\"I was sure wrong about Lady Tyvefelle's house; I barely got away with my life and lost my lock pick in the process.\"", 1, NULL, 0},
    {"Rog", "guardtalk_after", "item", "nethack.quest.rog.guardtalk_after.item_2", "\"You're back?  Even the Twain don't come back anymore.\"", 2, NULL, 0},
    {"Rog", "guardtalk_after", "item", "nethack.quest.rog.guardtalk_after.item_3", "\"Can you spare an old cutpurse a zorkmid for some grog?\"", 3, NULL, 0},
    {"Rog", "guardtalk_after", "item", "nethack.quest.rog.guardtalk_after.item_4", "\"Fritz tried to join the other side, and now he's hell-hound chow.\"", 4, NULL, 0},
    {"Rog", "guardtalk_after", "item", "nethack.quest.rog.guardtalk_after.item_5", "\"Be careful what you steal, I hear the boss has perfected turning rocks into worthless pieces of glass.\"", 5, NULL, 0},
    {"Rog", "guardtalk_before", "item", "nethack.quest.rog.guardtalk_before.item_1", "\"I hear that Lady Tyvefelle's household is lightly guarded.\"", 1, NULL, 0},
    {"Rog", "guardtalk_before", "item", "nethack.quest.rog.guardtalk_before.item_2", "\"You're back?  Even the Twain don't come back anymore.\"", 2, NULL, 0},
    {"Rog", "guardtalk_before", "item", "nethack.quest.rog.guardtalk_before.item_3", "\"Can you spare an old cutpurse a zorkmid for some grog?\"", 3, NULL, 0},
    {"Rog", "guardtalk_before", "item", "nethack.quest.rog.guardtalk_before.item_4", "\"Fritz tried to join the other side, and now he's hell-hound chow.\"", 4, NULL, 0},
    {"Rog", "guardtalk_before", "item", "nethack.quest.rog.guardtalk_before.item_5", "\"Be careful what you steal, I hear the boss has perfected turning rocks into worthless pieces of glass.\"", 5, NULL, 0},
    {"Rog", "hasamulet", "synopsis", "nethack.quest.rog.hasamulet.synopsis", "[Take the Amulet to the Astral Plane and find %ds temple.]", 0, nh_quest_bindings_641, 2},
    {"Rog", "hasamulet", "text", "nethack.quest.rog.hasamulet.text", "\"I see that with your abilities, and my brains, we could rule this world.\n\n\"All that we would need to be all-powerful is for you to take that little\ntrinket you've got there up to the Astral Plane.  From there, %d will\nshow you what to do with it.  Once that's done, we will be invincible!\"", 0, nh_quest_bindings_642, 1},
    {"Rog", "killed_nemesis", "synopsis", "nethack.quest.rog.killed_nemesis.synopsis", "[Before dying, %n tells you to use the %o wisely.]", 0, nh_quest_bindings_643, 2},
    {"Rog", "killed_nemesis", "text", "nethack.quest.rog.killed_nemesis.text", "\"I know what you are thinking, %p.  It is not too late for you\nto use %o wisely.  For the sake of your guild\n%sp, do what is right.\"\n\nYou sit and wait for death to come for %n, and then you\nbrace yourself for your next meeting with %l!", 0, nh_quest_bindings_644, 5},
    {"Rog", "leader_first", "synopsis", "nethack.quest.rog.leader_first.synopsis", "[You owe back dues to your guild.  You can pay them off if you're up to the job.]", 0, NULL, 0},
    {"Rog", "leader_first", "text", "nethack.quest.rog.leader_first.text", "\"Well, look who it is boys -- %p has come home.  You seem to have\nfallen behind in your dues.  I should kill you as an example to these\nother worthless cutpurses, but I have a better plan.  If you are ready\nmaybe you could work off your back dues by performing a little job for\nme.  Let us just see if you are ready...\"", 0, nh_quest_bindings_646, 1},
    {"Rog", "leader_last", "synopsis", "nethack.quest.rog.leader_last.synopsis", "[You must go.]", 0, NULL, 0},
    {"Rog", "leader_last", "text", "nethack.quest.rog.leader_last.text", "\"Well %gp, it looks like our friend has forgotten who is the boss\naround here.  Our friend seems to think that %rp have been put in\ncharge.  Wrong.  DEAD WRONG!\"\n\nYour sudden shift in surroundings prevents you from hearing the end\nof %ls curse.", 0, nh_quest_bindings_648, 6},
    {"Rog", "leader_next", "synopsis", "nethack.quest.rog.leader_next.synopsis", "[Are you stupid or are you ready?]", 0, NULL, 0},
    {"Rog", "leader_next", "text", "nethack.quest.rog.leader_next.text", "\"Well, I didn't expect to see you back.  It shows that you are either stupid,\nor you are finally ready to accept my offer.  Let us hope for your sake it\nisn't stupidity that brings you back.\"", 0, NULL, 0},
    {"Rog", "leader_other", "text", "nethack.quest.rog.leader_other.text", "\"Did you perhaps mistake me for some other %lt?  You must\nthink me as stupid as your behavior.  I warn you not to try my patience.\"", 0, nh_quest_bindings_651, 2},
    {"Rog", "locate_first", "text", "nethack.quest.rog.locate_first.text", "Those damn little hairs tell you that you are nearer to %o.", 0, nh_quest_bindings_652, 1},
    {"Rog", "locate_next", "text", "nethack.quest.rog.locate_next.text", "Not wanting to face %l without having stolen %o, you continue.", 0, nh_quest_bindings_653, 2},
    {"Rog", "nemesis_first", "text", "nethack.quest.rog.nemesis_first.text", "\"Ah!  You must be %ls ... er, `hero'.  A pleasure to meet you.\"", 0, nh_quest_bindings_654, 2},
    {"Rog", "nemesis_next", "text", "nethack.quest.rog.nemesis_next.text", "\"We meet again.  Please reconsider your actions.\"", 0, NULL, 0},
    {"Rog", "nemesis_other", "synopsis", "nethack.quest.rog.nemesis_other.synopsis", "[You cannot trust %l.]", 0, nh_quest_bindings_656, 1},
    {"Rog", "nemesis_other", "text", "nethack.quest.rog.nemesis_other.text", "\"Surely, %p, you have learned that you cannot trust any bargains\nthat %l has made.  I can show you how to continue on\nyour quest without having to run into him again.\"", 0, nh_quest_bindings_657, 2},
    {"Rog", "nemesis_wantsit", "synopsis", "nethack.quest.rog.nemesis_wantsit.synopsis", "[%lC should not have %o.]", 0, nh_quest_bindings_658, 3},
    {"Rog", "nemesis_wantsit", "text", "nethack.quest.rog.nemesis_wantsit.text", "\"Please, think for a moment about what you are doing.  Do you truly\nbelieve that %d would want %l to have\n%o?\"", 0, nh_quest_bindings_659, 3},
    {"Rog", "nexttime", "text", "nethack.quest.rog.nexttime.text", "Once again, you find yourself back in Ransmannsby.  Fond memories are\nreplaced by fear, knowing that %l is waiting for you.", 0, nh_quest_bindings_660, 1},
    {"Rog", "offeredit", "synopsis", "nethack.quest.rog.offeredit.synopsis", "[Take %o with you and go.]", 0, nh_quest_bindings_661, 1},
    {"Rog", "offeredit", "text", "nethack.quest.rog.offeredit.text", "\"Well, I'll be damned.  You got it.  I am proud of you, a fine %r\nyou've turned out to be.\n\n\"While you were gone I got to thinking, you and %o\ntogether could bring me more treasure than either of you apart, so why don't\nyou take it with you.  All I ask is a cut of whatever loot you come by.\nThat is a better deal than I offered %n.\n\n\"But, you see what happened to %n when he refused.\nDon't make me find another to send after you this time.\"", 0, nh_quest_bindings_662, 3},
    {"Rog", "offeredit2", "synopsis", "nethack.quest.rog.offeredit2.synopsis", "[Take %o and acquire the Amulet.]", 0, nh_quest_bindings_663, 1},
    {"Rog", "offeredit2", "text", "nethack.quest.rog.offeredit2.text", "%lC seems tempted to swap %o for\nthe mundane one you detect in his pocket, but noticing your alertness,\nevidently chickens out.\n\n\"Go filch the Amulet before someone else beats you to it.\n%Z are back the way you came, through the magic portal.\"", 0, nh_quest_bindings_664, 4},
    {"Rog", "othertime", "text", "nethack.quest.rog.othertime.text", "You rub your hands through your hair, hoping that the little ones on\nthe back of your neck stay down, and prepare yourself for your meeting\nwith %l.", 0, nh_quest_bindings_665, 1},
    {"Rog", "posthanks", "synopsis", "nethack.quest.rog.posthanks.synopsis", "[How about trading %o for something?]", 0, nh_quest_bindings_666, 1},
    {"Rog", "posthanks", "text", "nethack.quest.rog.posthanks.text", "\"Quite the little thief, aren't we, %p.  Can I interest you in a\nswap for %o?  Look around, anything in the keep\nis yours for the asking.\"", 0, nh_quest_bindings_667, 2},
    {"Sam", "assignquest", "synopsis", "nethack.quest.sam.assignquest.synopsis", "[You must enter %i, then regain %o from %n.]", 0, nh_quest_bindings_668, 3},
    {"Sam", "assignquest", "text", "nethack.quest.sam.assignquest.text", "\"Domo %p-san, indeed you are ready.  I can now tell you what\nit is that I require of you.\n\n\"The daimyo, %n, has betrayed us.  He has stolen from us\n%o and taken it to his donjon deep within\n%i.\n\n\"If I cannot show the emperor %o when he comes\nfor the festival he will know that I have failed in my duty, and\nrequest that I commit seppuku.\n\n\"You must gain entrance to %i and retrieve the\nemperor's property.  Be quick!  The emperor will be here for the\ncha-no-you in 5 sticks.\n\n\"Wakarimasu ka?\"", 0, nh_quest_bindings_669, 4},
    {"Sam", "badalign", "synopsis", "nethack.quest.sam.badalign.synopsis", "[When you can think %a and act %a then return.]", 0, nh_quest_bindings_670, 1},
    {"Sam", "badalign", "text", "nethack.quest.sam.badalign.text", "\"%p-san, you would do better to join the kyokaku.\n\n\"You have skills, but until you can call upon the bushido to know when and\nhow to use them you are not samurai.  When you can think %a and\nact %a then return.\"", 0, nh_quest_bindings_671, 2},
    {"Sam", "badlevel", "synopsis", "nethack.quest.sam.badlevel.synopsis", "[\"I require %Ra to defeat %n.  Return when you are ready.\"]", 0, nh_quest_bindings_672, 3},
    {"Sam", "badlevel", "text", "nethack.quest.sam.badlevel.text", "\"%p-san, you have learned well and honored your family.\nI require the skills of %Ra in order to defeat %n.\nGo and seek out teachers.  Learn what they have learned.  When you\nare ready, return to me.\"", 0, nh_quest_bindings_673, 4},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_1", "\"Ahh, I finally meet the daimyo of the kyokaku!\"", 1, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_10", "\"Your master was a poor teacher.  You will pay for his mistakes in your teaching.\"", 10, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_2", "\"There is no honor for me in your death.\"", 2, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_3", "\"You know that I cannot resash my swords until they have killed.\"", 3, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_4", "\"Your presence only compounds the dishonor of %l in not coming %liself.\"", 4, nh_quest_bindings_678, 2},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_5", "\"I will make tea with your hair and serve it to %l.\"", 5, nh_quest_bindings_679, 1},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_6", "\"Your fear shows in your eyes, coward!\"", 6, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_7", "\"I have not heard of you, %p-san; has your life been that unworthy?\"", 7, nh_quest_bindings_681, 1},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_8", "\"If you will not obey me, you will die.\"", 8, NULL, 0},
    {"Sam", "discourage", "item", "nethack.quest.sam.discourage.item_9", "\"Kneel now and make the two cuts of honor.  I will tell your %sp of your honorable death.\"", 9, nh_quest_bindings_683, 2},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_1", "\"To defeat %n you must overcome the seven emotions: hate, adoration, joy, anxiety, anger, grief, and fear.\"", 1, nh_quest_bindings_684, 1},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_10", "\"Sharpen your swords and your wits for the task before you.\"", 10, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_2", "\"Remember your honor is my honor, you perform in my name.\"", 2, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_3", "\"I will go to the temple and burn incense for your safe return.\"", 3, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_4", "\"Sayonara.\"", 4, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_5", "\"There can be honor in defeat, but no gain.\"", 5, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_6", "\"Your kami must be strong in order to succeed.\"", 6, NULL, 0},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_7", "\"You are indeed a worthy %R, but now you must be a worthy samurai.\"", 7, nh_quest_bindings_691, 1},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_8", "\"If you fail, %n will be like a tai-fun on the land.\"", 8, nh_quest_bindings_692, 1},
    {"Sam", "encourage", "item", "nethack.quest.sam.encourage.item_9", "\"If you are truly %a, %d will listen.\"", 9, nh_quest_bindings_693, 2},
    {"Sam", "firsttime", "synopsis", "nethack.quest.sam.firsttime.synopsis", "[The banner of %n flies above town.  What has happened to %l?]", 0, nh_quest_bindings_694, 2},
    {"Sam", "firsttime", "text", "nethack.quest.sam.firsttime.text", "Even before your senses adjust, you recognize the kami of\n%H.\n\nYou %x the standard of your teki, %n, flying above\nthe town.  How could such a thing have happened?  Why are ninja\nwandering freely; where are the samurai of your daimyo, %l?\n\nYou quickly say a prayer to Izanagi and Izanami and walk towards\ntown.", 0, nh_quest_bindings_695, 4},
    {"Sam", "goal_alt", "text", "nethack.quest.sam.goal_alt.text", "As you arrive once again at the home of %n.", 0, nh_quest_bindings_696, 1},
    {"Sam", "goal_first", "synopsis", "nethack.quest.sam.goal_first.synopsis", "[You feel the taunts %n, but after offering a prayer to %d, you proceed.]", 0, nh_quest_bindings_697, 2},
    {"Sam", "goal_first", "text", "nethack.quest.sam.goal_first.text", "In your mind, you hear the taunts of %n.\n\nYou become like the rice plant and bend to the ground, offering a\nprayer to %d.  But when the wind has passed, you stand\nproudly again.  Putting your kami in the hands of fate, you advance.", 0, nh_quest_bindings_698, 2},
    {"Sam", "goal_next", "text", "nethack.quest.sam.goal_next.text", "As you arrive once again at the home of %n, your thoughts\nturn only to %o.", 0, nh_quest_bindings_699, 2},
    {"Sam", "gotit", "synopsis", "nethack.quest.sam.gotit.synopsis", "[You feel the power of %o and are humbled.]", 0, nh_quest_bindings_700, 1},
    {"Sam", "gotit", "text", "nethack.quest.sam.gotit.text", "As you pick up %o, you feel the strength of its karma.\nYou realize at once why so many good samurai had to die to defend it.\nYou are humbled knowing that you hold one of the artifacts of the\nsun goddess.", 0, nh_quest_bindings_701, 1},
    {"Sam", "guardtalk_after", "item", "nethack.quest.sam.guardtalk_after.item_1", "\"Come, join us in celebrating with some sake.\"", 1, NULL, 0},
    {"Sam", "guardtalk_after", "item", "nethack.quest.sam.guardtalk_after.item_2", "\"Ikaga desu ka?\"", 2, NULL, 0},
    {"Sam", "guardtalk_after", "item", "nethack.quest.sam.guardtalk_after.item_3", "\"You have brought our clan and %l much honor.\"", 3, nh_quest_bindings_704, 1},
    {"Sam", "guardtalk_after", "item", "nethack.quest.sam.guardtalk_after.item_4", "\"Please %r, sit for a while and tell us how you overcame the Ninja.\"", 4, nh_quest_bindings_705, 1},
    {"Sam", "guardtalk_after", "item", "nethack.quest.sam.guardtalk_after.item_5", "\"%lC still lives!  You have saved us from becoming ronin.\"", 5, nh_quest_bindings_706, 2},
    {"Sam", "guardtalk_before", "item", "nethack.quest.sam.guardtalk_before.item_1", "\"To succeed, you must walk like a butterfly on the wind.\"", 1, NULL, 0},
    {"Sam", "guardtalk_before", "item", "nethack.quest.sam.guardtalk_before.item_2", "\"Ikaga desu ka?\"", 2, NULL, 0},
    {"Sam", "guardtalk_before", "item", "nethack.quest.sam.guardtalk_before.item_3", "\"I fear for The Land of The Gods.\"", 3, NULL, 0},
    {"Sam", "guardtalk_before", "item", "nethack.quest.sam.guardtalk_before.item_4", "\"%nC has hired the Ninja -- be careful.\"", 4, nh_quest_bindings_710, 2},
    {"Sam", "guardtalk_before", "item", "nethack.quest.sam.guardtalk_before.item_5", "\"If %o is not returned, we will all be ronin.\"", 5, nh_quest_bindings_711, 1},
    {"Sam", "hasamulet", "synopsis", "nethack.quest.sam.hasamulet.synopsis", "[Take the Amulet to the Astral Plane to finish your task.]", 0, NULL, 0},
    {"Sam", "hasamulet", "text", "nethack.quest.sam.hasamulet.text", "\"Ah, %p-sama.  You have wasted your efforts returning home.\nNow that you are in possession of the Amulet, you are honor-bound to\nfinish the quest you have undertaken.  There will be plenty of time\nfor saki and stories when you have finished.\n\n\"Go now, and may our prayers be a wind at your back.\"", 0, nh_quest_bindings_713, 1},
    {"Sam", "killed_nemesis", "synopsis", "nethack.quest.sam.killed_nemesis.synopsis", "[%nC dies without honor.]", 0, nh_quest_bindings_714, 2},
    {"Sam", "killed_nemesis", "text", "nethack.quest.sam.killed_nemesis.text", "Your healing skills tell you that %ns wounds are mortal.\n\nYou know that the bushido tells you to finish him and let his kami\ndie with honor, but the thought of so many samurai dead due to this\nman's dishonor prevents you from giving the final blow.\n\nYou order that his unwashed head be given to the crows and his body\nthrown into the sea.", 0, nh_quest_bindings_715, 2},
    {"Sam", "leader_first", "synopsis", "nethack.quest.sam.leader_first.synopsis", "[%lC needs someone to lead %lj samurai against %n.  Are you ready?]", 0, nh_quest_bindings_716, 4},
    {"Sam", "leader_first", "text", "nethack.quest.sam.leader_first.text", "\"Ah, %p-san, it is good to see you again.  I need someone who can\nlead my samurai against %n.  If you are ready, you will be\nthat person.\"", 0, nh_quest_bindings_717, 2},
    {"Sam", "leader_last", "synopsis", "nethack.quest.sam.leader_last.synopsis", "[Leave and do not come back.]", 0, NULL, 0},
    {"Sam", "leader_last", "text", "nethack.quest.sam.leader_last.text", "\"You are no longer my samurai, %p.\n\n\"Hara-kiri is denied.  You are ordered to shave your head and then to\nbecome a monk.  Your fief and family are forfeit.  Wakarimasu ka?\"", 0, nh_quest_bindings_719, 1},
    {"Sam", "leader_next", "text", "nethack.quest.sam.leader_next.text", "\"Once again, %p-san, you kneel before me.  Are you yet capable of\nbeing my vassal?\"", 0, nh_quest_bindings_720, 1},
    {"Sam", "leader_other", "synopsis", "nethack.quest.sam.leader_other.synopsis", "[Are you truly a samurai?]", 0, NULL, 0},
    {"Sam", "leader_other", "text", "nethack.quest.sam.leader_other.text", "\"You begin to test my matsu, %p-san.\nIf you cannot determine what I want in a samurai, how can I rely on you\nto figure out what I need from a samurai?\"", 0, nh_quest_bindings_722, 1},
    {"Sam", "locate_first", "text", "nethack.quest.sam.locate_first.text", "You instinctively reach for your swords.  You do not recognize the\nlay of this land, but you know that your teki are everywhere.", 0, NULL, 0},
    {"Sam", "locate_next", "text", "nethack.quest.sam.locate_next.text", "Thankful that your %sp at %H cannot see\nyour fear, you prepare again to advance.", 0, nh_quest_bindings_724, 3},
    {"Sam", "nemesis_first", "text", "nethack.quest.sam.nemesis_first.text", "\"Ah, so it is to be you, %p-san.  I offer you seppuku.\nI will be your second if you wish.\"", 0, nh_quest_bindings_725, 1},
    {"Sam", "nemesis_next", "text", "nethack.quest.sam.nemesis_next.text", "\"I have offered you the honorable exit.  Now I will have your\nhead to send unwashed to %l.\"", 0, nh_quest_bindings_726, 1},
    {"Sam", "nemesis_other", "text", "nethack.quest.sam.nemesis_other.text", "\"After I have dispatched you, I will curse your kami.\"", 0, NULL, 0},
    {"Sam", "nemesis_wantsit", "text", "nethack.quest.sam.nemesis_wantsit.text", "\"You have fought my samurai; surely you must know that you\nwill not be able to take %o back to\n%H.\"", 0, nh_quest_bindings_728, 2},
    {"Sam", "nexttime", "text", "nethack.quest.sam.nexttime.text", "Once again, you are back at %H.", 0, nh_quest_bindings_729, 1},
    {"Sam", "offeredit", "synopsis", "nethack.quest.sam.offeredit.synopsis", "[The emperor wants you to take %o and recover the Amulet.]", 0, nh_quest_bindings_730, 1},
    {"Sam", "offeredit", "text", "nethack.quest.sam.offeredit.text", "As you bow before %l, he welcomes you:\n\n    \"You have brought your family great honor, %p-sama.\n\n    \"While you have been gone the emperor's advisors have discovered in\n    the ancient texts that the karma of the samurai who seeks to recover\n    the Amulet and the karma of %o are joined\n    as the seasons join to make a year.\n\n    \"Because you have shown such fidelity, the emperor requests\n    that you take leave of other obligations and continue on the\n    road that fate has set your feet upon.  I would consider it\n    an honor if you would allow me to watch your household until\n    you return with the Amulet.\"\n\nWith that, %l bows, and places his sword atop\n%o.", 0, nh_quest_bindings_731, 3},
    {"Sam", "offeredit2", "synopsis", "nethack.quest.sam.offeredit2.synopsis", "[Take %o, return to %Z, and recover the Amulet.]", 0, nh_quest_bindings_732, 2},
    {"Sam", "offeredit2", "text", "nethack.quest.sam.offeredit2.text", "%l holds %o tightly for a moment, then returns\nhis gaze to you.\n\n\"The time is ripe to recover the Amulet.  Return to %Z\nthrough the magic portal that transported you here so that you may\nachieve the destiny which awaits you.\"", 0, nh_quest_bindings_733, 3},
    {"Sam", "othertime", "synopsis", "nethack.quest.sam.othertime.synopsis", "[%HC is threatened by %n.]", 0, nh_quest_bindings_734, 3},
    {"Sam", "othertime", "text", "nethack.quest.sam.othertime.text", "You are back at %H.\n\nInstantly you sense a subtle change in your karma.  You seem to know that\nif you do not succeed in your quest, %n will have destroyed\nthe kami of %H before you return again.", 0, nh_quest_bindings_735, 2},
    {"Sam", "posthanks", "text", "nethack.quest.sam.posthanks.text", "%lC bows.  \"%p-sama, tell us of your search for the Amulet.\"", 0, nh_quest_bindings_736, 3},
    {"Tou", "assignquest", "synopsis", "nethack.quest.tou.assignquest.synopsis", "[Enter %i and recover %o from %n.]", 0, nh_quest_bindings_737, 3},
    {"Tou", "assignquest", "text", "nethack.quest.tou.assignquest.text", "\"You have indeed proven yourself a worthy %c, %p.\n\n\"But now your kinfolk and I must ask you to put aside your travels and\nhelp us in our time of need.  After you left us we elected a new mayor,\n%n.  He proved to be a most heinous and vile creature.\n\n\"Soon after taking office he absconded with %o\nand fled town, leaving behind his henchmen to rule over us.  In order\nfor us to regain control of our town, you must enter %i\nand recover %o.\n\n\"Do not be distracted on your quest.  If you do not return quickly I fear\nthat all will be lost.  Let us both pray now that %d will guide you\nand keep you safe.\"", 0, nh_quest_bindings_738, 6},
    {"Tou", "badalign", "synopsis", "nethack.quest.tou.badalign.synopsis", "[You are not sufficiently %a.  Return when you are.]", 0, nh_quest_bindings_739, 1},
    {"Tou", "badalign", "text", "nethack.quest.tou.badalign.text", "\"It would be an affront to %d to have one not true to the\n%a path undertake her bidding.\n\n\"You must not return to us until you have purified yourself of these\nbad influences on your actions.  Remember, only by following the %a\npath can you hope to overcome the obstacles you will face.\"", 0, nh_quest_bindings_740, 2},
    {"Tou", "badlevel", "synopsis", "nethack.quest.tou.badlevel.synopsis", "[Return when you are %Ra.]", 0, nh_quest_bindings_741, 2},
    {"Tou", "badlevel", "text", "nethack.quest.tou.badlevel.text", "\"There is still too much that you have to learn before you can undertake\nthe next step.  Return to us as a proven %R, and perhaps then\nyou will be ready.\n\n\"Go back now, and may the teachings of %d serve you well.\"", 0, nh_quest_bindings_742, 2},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_1", "\"I defeated %l and I will defeat you, %p.\"", 1, nh_quest_bindings_743, 2},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_10", "\"How do you spell %p?  I want to ensure the marker on your grave is correct as a warning to your %sp.\"", 10, nh_quest_bindings_744, 3},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_2", "\"Where is %d now!  You must realize no one can help you here.\"", 2, nh_quest_bindings_745, 1},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_3", "\"Beg for mercy now and I may be lenient on you.\"", 3, NULL, 0},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_4", "\"If you were not so %a, you might have stood a chance.\"", 4, nh_quest_bindings_747, 1},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_5", "\"Vengeance is mine at last, %p.\"", 5, nh_quest_bindings_748, 1},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_6", "\"I only wish that %l had a more worthy %r to send against me.\"", 6, nh_quest_bindings_749, 2},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_7", "\"With %o in my possession you cannot hope to defeat me.\"", 7, nh_quest_bindings_750, 1},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_8", "\"%nC has never been defeated, NEVER!\"", 8, nh_quest_bindings_751, 2},
    {"Tou", "discourage", "item", "nethack.quest.tou.discourage.item_9", "\"Are you truly the best %H has to send against me?  I pity %l.\"", 9, nh_quest_bindings_752, 2},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_1", "\"Do not be fooled by the false promises of %n.\"", 1, nh_quest_bindings_753, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_10", "\"Let all who meet you on your journey know that you are on a quest for %l and grant safe passage.\"", 10, nh_quest_bindings_754, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_2", "\"To enter %i you must pass many traps.\"", 2, nh_quest_bindings_755, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_3", "\"If you do not return with %o, your quest will be in vain.\"", 3, nh_quest_bindings_756, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_4", "\"Do not be afraid to call upon %d if you truly need help.\"", 4, nh_quest_bindings_757, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_5", "\"If you do not destroy %n, he will follow you back here!\"", 5, nh_quest_bindings_758, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_6", "\"Take %o from %n and you may be able to defeat him.\"", 6, nh_quest_bindings_759, 2},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_7", "\"You must hurry, %p!\"", 7, nh_quest_bindings_760, 1},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_8", "\"You are like %Sa to me, %p.  Do not let me down.\"", 8, nh_quest_bindings_761, 3},
    {"Tou", "encourage", "item", "nethack.quest.tou.encourage.item_9", "\"If you are %a at all times you may succeed, %p.\"", 9, nh_quest_bindings_762, 2},
    {"Tou", "firsttime", "synopsis", "nethack.quest.tou.firsttime.synopsis", "[You find yourself back at %H, but the quiet is ominous.]", 0, nh_quest_bindings_763, 1},
    {"Tou", "firsttime", "text", "nethack.quest.tou.firsttime.text", "You breathe a sigh of relief as you find yourself back in the familiar\nsurroundings of %H.\n\nYou quickly notice that things do not appear the way they did when you\nleft.  The town is dark and quiet.  There are no sounds coming from\nbehind the town walls, and no campfires burning in the fields.  As a\nmatter of fact, you do not %x any movement in the fields at all, and\nthe crops seem as though they have been untended for many weeks.", 0, nh_quest_bindings_764, 2},
    {"Tou", "goal_alt", "text", "nethack.quest.tou.goal_alt.text", "You have returned to %ns lair.", 0, nh_quest_bindings_765, 1},
    {"Tou", "goal_first", "text", "nethack.quest.tou.goal_first.text", "You sense the presence of %o.", 0, nh_quest_bindings_766, 1},
    {"Tou", "goal_next", "text", "nethack.quest.tou.goal_next.text", "You gain confidence, knowing that you may soon be united with\n%o.", 0, nh_quest_bindings_767, 1},
    {"Tou", "gotit", "synopsis", "nethack.quest.tou.gotit.synopsis", "[You pick up %o and feel relief.  Return it to %l.]", 0, nh_quest_bindings_768, 2},
    {"Tou", "gotit", "text", "nethack.quest.tou.gotit.text", "As you pick up %o, you feel a great\nweight has been lifted from your shoulders.  Your only thoughts are\nto quickly return to %H and find %l.", 0, nh_quest_bindings_769, 3},
    {"Tou", "guardtalk_after", "item", "nethack.quest.tou.guardtalk_after.item_1", "\"Gehennom on 5 zorkmids a day -- more like 500 a day if you ask me.\"", 1, NULL, 0},
    {"Tou", "guardtalk_after", "item", "nethack.quest.tou.guardtalk_after.item_2", "\"Do you know where I could find some nice postcards of The Gnomish Mines?\"", 2, NULL, 0},
    {"Tou", "guardtalk_after", "item", "nethack.quest.tou.guardtalk_after.item_3", "\"Have you tried the weird toilets?\"", 3, NULL, 0},
    {"Tou", "guardtalk_after", "item", "nethack.quest.tou.guardtalk_after.item_4", "\"If you stick around, I'll show you the pictures from my latest trip.\"", 4, NULL, 0},
    {"Tou", "guardtalk_after", "item", "nethack.quest.tou.guardtalk_after.item_5", "\"Did you bring me back any souvenirs?\"", 5, NULL, 0},
    {"Tou", "guardtalk_before", "item", "nethack.quest.tou.guardtalk_before.item_1", "\"Gehennom on 5 zorkmids a day -- more like 500 a day if you ask me.\"", 1, NULL, 0},
    {"Tou", "guardtalk_before", "item", "nethack.quest.tou.guardtalk_before.item_2", "\"Do you know where I could find some nice postcards of The Gnomish Mines?\"", 2, NULL, 0},
    {"Tou", "guardtalk_before", "item", "nethack.quest.tou.guardtalk_before.item_3", "\"Have you tried the weird toilets?\"", 3, NULL, 0},
    {"Tou", "guardtalk_before", "item", "nethack.quest.tou.guardtalk_before.item_4", "\"Don't stay at the Inn, I hear the food is terrible and it has rats.\"", 4, NULL, 0},
    {"Tou", "guardtalk_before", "item", "nethack.quest.tou.guardtalk_before.item_5", "\"They told me that this was the off season!\"", 5, NULL, 0},
    {"Tou", "hasamulet", "synopsis", "nethack.quest.tou.hasamulet.synopsis", "[You have the Amulet.  Take it to the Astral Plane to finish your task.]", 0, NULL, 0},
    {"Tou", "hasamulet", "text", "nethack.quest.tou.hasamulet.text", "\"Stand back and let me look at you, %p.\nNow that you have recovered the Amulet of Yendor, I'm afraid living\nout your days in %H would seem pretty tame.\n\n\"You have come too far to stop now, for there are still more tasks that\nour oral history foretells for you.  Forever more, though, your name shall\nbe spoken by the %gP with awe.  You are truly an inspiration to your\n%sp!\"", 0, nh_quest_bindings_781, 6},
    {"Tou", "killed_nemesis", "synopsis", "nethack.quest.tou.killed_nemesis.synopsis", "[%nC curses at you as %nh dies.]", 0, nh_quest_bindings_782, 3},
    {"Tou", "killed_nemesis", "text", "nethack.quest.tou.killed_nemesis.text", "You turn in the direction of %n.  As his earthly body begins\nto vanish before your eyes, you hear him curse:\n\n    \"You shall never be rid of me, %p!\n    I will find you where ever you go and regain what is rightly mine.\"", 0, nh_quest_bindings_783, 2},
    {"Tou", "leader_first", "synopsis", "nethack.quest.tou.leader_first.synopsis", "[Someone must defeat %n.  Are your ready?]", 0, nh_quest_bindings_784, 1},
    {"Tou", "leader_first", "text", "nethack.quest.tou.leader_first.text", "\"Is it really you, %p!  I had given up hope for your return.\nAs you can %x, we are desperately in need of your talents.  Someone must\ndefeat %n if our town is to become what it once was.\n\n\"Let me see if you are ready to be that someone.\"", 0, nh_quest_bindings_785, 3},
    {"Tou", "leader_last", "synopsis", "nethack.quest.tou.leader_last.synopsis", "[Leave %H and never return.]", 0, nh_quest_bindings_786, 1},
    {"Tou", "leader_last", "text", "nethack.quest.tou.leader_last.text", "\"It is too late, %p.  You are not even worthy to die amongst us.\nLeave %H and never return.\"", 0, nh_quest_bindings_787, 2},
    {"Tou", "leader_next", "text", "nethack.quest.tou.leader_next.text", "\"Things are getting worse, %p.  I hope that this time you are ready.\"", 0, nh_quest_bindings_788, 1},
    {"Tou", "leader_other", "text", "nethack.quest.tou.leader_other.text", "\"I hope that for the sake of %H you have prepared yourself this time.\"", 0, nh_quest_bindings_789, 1},
    {"Tou", "locate_first", "synopsis", "nethack.quest.tou.locate_first.synopsis", "[You %x the handiwork of %ns henchlings.]", 0, nh_quest_bindings_790, 3},
    {"Tou", "locate_first", "text", "nethack.quest.tou.locate_first.text", "Only your faith in %d keeps you from trembling.  You %x\nthe handiwork of %ns henchlings everywhere.", 0, nh_quest_bindings_791, 4},
    {"Tou", "locate_next", "text", "nethack.quest.tou.locate_next.text", "You know that this time you must find and destroy %n.", 0, nh_quest_bindings_792, 1},
    {"Tou", "nemesis_first", "synopsis", "nethack.quest.tou.nemesis_first.synopsis", "[%rA will not defeat me.]", 0, nh_quest_bindings_793, 2},
    {"Tou", "nemesis_first", "text", "nethack.quest.tou.nemesis_first.text", "\"So, %p, %l thinks that you can wrest\n%o from me!\n\n\"It only proves how desperate he has become that he sends %ra to\ntry to defeat me.  When this day is over, I will have you enslaved\nin the mines where you will rue the day that you ever entered\n%i.\"", 0, nh_quest_bindings_794, 6},
    {"Tou", "nemesis_next", "text", "nethack.quest.tou.nemesis_next.text", "\"I let you live the last time because it gave me pleasure.\nThis time I will destroy you, %p.\"", 0, nh_quest_bindings_795, 1},
    {"Tou", "nemesis_other", "synopsis", "nethack.quest.tou.nemesis_other.synopsis", "[Run away or you will suffer severely.]", 0, NULL, 0},
    {"Tou", "nemesis_other", "text", "nethack.quest.tou.nemesis_other.text", "\"These meetings come to bore me.  You disturb my workings with\n%o.\n\n\"If you do not run away now, I will inflict so much suffering on you that\n%l will feel guilty for ever having sent his %S to me!\"", 0, nh_quest_bindings_797, 3},
    {"Tou", "nemesis_wantsit", "synopsis", "nethack.quest.tou.nemesis_wantsit.synopsis", "[\"Return %o to me and we will rule %H.\"]", 0, nh_quest_bindings_798, 2},
    {"Tou", "nemesis_wantsit", "text", "nethack.quest.tou.nemesis_wantsit.text", "\"You fool.  You do not know how to call upon the powers of\n%o.\n\n\"Return it to me and I will teach you how to use it, and together we\nwill rule %H.  But do so now, as my patience grows thin.\"", 0, nh_quest_bindings_799, 2},
    {"Tou", "nexttime", "text", "nethack.quest.tou.nexttime.text", "Once again, you are back at %H.", 0, nh_quest_bindings_800, 1},
    {"Tou", "offeredit", "synopsis", "nethack.quest.tou.offeredit.synopsis", "[Take %o and with %ds guidance, recover the Amulet.]", 0, nh_quest_bindings_801, 3},
    {"Tou", "offeredit", "text", "nethack.quest.tou.offeredit.text", "As %l detects the presence of %o,\nhe almost smiles for the first time in many a full moon.\n\nAs he looks up from %o he says:\n\n    \"You have recovered %o.  You are its\n    owner now, but not its master.  Let it work with you as you continue\n    your journey.  With its help, and %d to guide you on the\n    %a path, you may yet recover the Amulet of Yendor.\"", 0, nh_quest_bindings_802, 4},
    {"Tou", "offeredit2", "synopsis", "nethack.quest.tou.offeredit2.synopsis", "[Keep %o and return to %Z through the portal.]", 0, nh_quest_bindings_803, 2},
    {"Tou", "offeredit2", "text", "nethack.quest.tou.offeredit2.text", "\"%oC is yours now.  %Z\nawait your return through the magic portal that brought you here.\"", 0, nh_quest_bindings_804, 3},
    {"Tou", "othertime", "text", "nethack.quest.tou.othertime.text", "You are back at %H.\nThings appear to have become so bad that you fear that soon\n%H will not be here to return to.", 0, nh_quest_bindings_805, 1},
    {"Tou", "posthanks", "text", "nethack.quest.tou.posthanks.text", "\"I could not be more proud than if you were my own %S, %p!\nTell me of your adventures in quest of the Amulet of Yendor.\"", 0, nh_quest_bindings_806, 2},
    {"Val", "assignquest", "synopsis", "nethack.quest.val.assignquest.synopsis", "[Find %i; defeat %n; return with %o.]", 0, nh_quest_bindings_807, 3},
    {"Val", "assignquest", "text", "nethack.quest.val.assignquest.text", "\"It is not clear, %p, for my sight is limited without our relic.\nBut it is now likely that you can defeat %n, and recover\n%o.\n\n\"A short time ago, %n and his minions attacked this place.  They\nopened the huge volcanic vents you %x about the hill, and attacked.  I knew\nthat this was to come to pass, and had asked %d for a group of %gP\nto help defend this place.  The few you %x here are the mightiest of\nValhalla's own, and are all that are left of one hundred %d sent.\n\n\"Despite the great and glorious battle we fought, %n managed at\nlast to steal %o.  This has upset the balance of the universe,\nand unless %oh is returned into my care, %n may start Ragnarok.\n\n\"You must find the entrance to %i.  Travel downward\nfrom there and you will find %ns lair.  Defeat him and\nreturn %o to me.\"", 0, nh_quest_bindings_808, 10},
    {"Val", "badalign", "synopsis", "nethack.quest.val.badalign.synopsis", "[You have strayed from the %a path.  Return after you purify yourself.]", 0, nh_quest_bindings_809, 1},
    {"Val", "badalign", "text", "nethack.quest.val.badalign.text", "\"NO!  This is terrible.  I see you becoming an ally of %n, and\nleading his armies in the final great battles.  This must not come to\npass!  You have strayed from the %a path.  You must purge yourself,\nand return here only when you have regained a state of purity.\"", 0, nh_quest_bindings_810, 2},
    {"Val", "badlevel", "synopsis", "nethack.quest.val.badlevel.synopsis", "[Come back when you are %Ra.]", 0, nh_quest_bindings_811, 2},
    {"Val", "badlevel", "text", "nethack.quest.val.badlevel.text", "\"I see you and %n fighting, %p.  But you are not prepared and\nshall die at %ns hand if you proceed.  No.  This will not do.\nGo back out into the world, and grow more experienced at the ways of war.\nOnly when you have returned %Ra will you be able to defeat %n.\"", 0, nh_quest_bindings_812, 5},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_1", "\"I am your death, %c.\"", 1, nh_quest_bindings_813, 1},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_10", "\"Your body I destroy now, your soul when my hordes overrun Valhalla!\"", 10, NULL, 0},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_2", "\"You cannot prevail, %r.  I have foreseen your every move.\"", 2, nh_quest_bindings_815, 1},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_3", "\"With you out of the way, Valhalla will be mine for the taking.\"", 3, NULL, 0},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_4", "\"I killed scores of %ds best when I took %o. Do you really think that one %c can stand against me?\"", 4, nh_quest_bindings_817, 4},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_5", "\"Who bears the souls of %cP to Valhalla, %r?\"", 5, nh_quest_bindings_818, 3},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_6", "\"No, %d cannot help you here.\"", 6, nh_quest_bindings_819, 1},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_7", "\"Some instrument of %d you are, %p.  You are a weakling!\"", 7, nh_quest_bindings_820, 2},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_8", "\"Never have I seen %ca so clumsy in battle.\"", 8, nh_quest_bindings_821, 2},
    {"Val", "discourage", "item", "nethack.quest.val.discourage.item_9", "\"You die now, little %s.\"", 9, nh_quest_bindings_822, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_1", "\"Go with the blessings of %d.\"", 1, nh_quest_bindings_823, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_10", "\"Remember your training, %p.  You can succeed.\"", 10, nh_quest_bindings_824, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_2", "\"Call upon %d when you are in need.\"", 2, nh_quest_bindings_825, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_3", "\"Use %o if you can.  It will protect you.\"", 3, nh_quest_bindings_826, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_4", "\"Magical cold is very effective against %n.\"", 4, nh_quest_bindings_827, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_5", "\"To face %n, you will need to be immune to fire.\"", 5, nh_quest_bindings_828, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_6", "\"May %d strengthen your sword-arm.\"", 6, nh_quest_bindings_829, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_7", "\"Trust in %d.  He will not desert you.\"", 7, nh_quest_bindings_830, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_8", "\"It becomes more likely that Ragnarok will come with every passing moment. You must hurry, %p.\"", 8, nh_quest_bindings_831, 1},
    {"Val", "encourage", "item", "nethack.quest.val.encourage.item_9", "\"If %n can master %o, he will be powerful enough to face %d far earlier than is fated.  This must not be!\"", 9, nh_quest_bindings_832, 3},
    {"Val", "firsttime", "synopsis", "nethack.quest.val.firsttime.synopsis", "[You arrive below %H.  Something is wrong; there is lava present.]", 0, nh_quest_bindings_833, 1},
    {"Val", "firsttime", "text", "nethack.quest.val.firsttime.text", "You materialize at the base of a snowy hill.  Atop the hill sits\na place you know well, %H.  You immediately realize\nthat something here is very wrong!\n\nIn places, the snow and ice have been melted into steaming pools of\nwater.  Fumaroles and pools of bubbling lava surround the hill.\nThe stench of sulphur is carried through the air, and you %x creatures\nthat should not be able to live in this environment moving towards you.", 0, nh_quest_bindings_834, 2},
    {"Val", "goal_first", "synopsis", "nethack.quest.val.goal_first.synopsis", "[This is the lair of %n.]", 0, nh_quest_bindings_835, 1},
    {"Val", "goal_first", "text", "nethack.quest.val.goal_first.text", "Through clouds of sulphurous gasses, you %x a rock palisade\nsurrounded with a moat of bubbling lava.  You remember the description\nfrom something that %l said.  This is the lair of %n.", 0, nh_quest_bindings_836, 3},
    {"Val", "goal_next", "text", "nethack.quest.val.goal_next.text", "Once again, you stand in sight of %ns lair.", 0, nh_quest_bindings_837, 2},
    {"Val", "gotit", "synopsis", "nethack.quest.val.gotit.synopsis", "[You must return %o to %l.]", 0, nh_quest_bindings_838, 2},
    {"Val", "gotit", "text", "nethack.quest.val.gotit.text", "As you pick up %o, your mind is suddenly filled with images,\nand you perceive all of the possibilities of each potential choice you\ncould make.  As you begin to control and channel your thoughts, you\nrealize that you must return %o to %l immediately.", 0, nh_quest_bindings_839, 2},
    {"Val", "guardtalk_after", "item", "nethack.quest.val.guardtalk_after.item_1", "\"Hail, and well met, brave %c.\"", 1, nh_quest_bindings_840, 1},
    {"Val", "guardtalk_after", "item", "nethack.quest.val.guardtalk_after.item_2", "\"May %d guide your steps, %p.\"", 2, nh_quest_bindings_841, 2},
    {"Val", "guardtalk_after", "item", "nethack.quest.val.guardtalk_after.item_3", "\"%lC told us you had succeeded!\"", 3, nh_quest_bindings_842, 2},
    {"Val", "guardtalk_after", "item", "nethack.quest.val.guardtalk_after.item_4", "\"You recovered %o just in time, %p.\"", 4, nh_quest_bindings_843, 2},
    {"Val", "guardtalk_after", "item", "nethack.quest.val.guardtalk_after.item_5", "\"Hail %d, for delivering %o back to us.\"", 5, nh_quest_bindings_844, 2},
    {"Val", "guardtalk_before", "item", "nethack.quest.val.guardtalk_before.item_1", "\"Hail, and well met, brave %c.\"", 1, nh_quest_bindings_845, 1},
    {"Val", "guardtalk_before", "item", "nethack.quest.val.guardtalk_before.item_2", "\"May %d guide your steps, %p.\"", 2, nh_quest_bindings_846, 2},
    {"Val", "guardtalk_before", "item", "nethack.quest.val.guardtalk_before.item_3", "\"%lC weakens.  Without %o, her foresight is dim.\"", 3, nh_quest_bindings_847, 3},
    {"Val", "guardtalk_before", "item", "nethack.quest.val.guardtalk_before.item_4", "\"You must hurry, %p, else Ragnarok may well come.\"", 4, nh_quest_bindings_848, 1},
    {"Val", "guardtalk_before", "item", "nethack.quest.val.guardtalk_before.item_5", "\"I would deal with this foul %n myself, but %d forbids it.\"", 5, nh_quest_bindings_849, 2},
    {"Val", "hasamulet", "synopsis", "nethack.quest.val.hasamulet.synopsis", "[Take the Amulet to %ds temple on the Astral Plane and offer it.]", 0, nh_quest_bindings_850, 2},
    {"Val", "hasamulet", "text", "nethack.quest.val.hasamulet.text", "\"Excellent, %p.  I see you have recovered the Amulet!\n\n\"You must take the Amulet to the Great Temple of %d, on the Astral\nPlane.  There you must offer the Amulet to %d.\n\n\"Go now, my %S.  I cannot tell you your fate, as the power of the\nAmulet interferes with mine.  I hope for your success.\"", 0, nh_quest_bindings_851, 3},
    {"Val", "killed_nemesis", "synopsis", "nethack.quest.val.killed_nemesis.synopsis", "[%nC dies.]", 0, nh_quest_bindings_852, 2},
    {"Val", "killed_nemesis", "text", "nethack.quest.val.killed_nemesis.text", "A look of surprise and horror appears on %ns face.\n\n    \"No!!!  %o has lied to me!  I have been misled!\"\n\nSuddenly, %n grasps his head and screams in agony, then dies.", 0, nh_quest_bindings_853, 3},
    {"Val", "leader_first", "synopsis", "nethack.quest.val.leader_first.synopsis", "[We need your aid.  Are you ready?]", 0, NULL, 0},
    {"Val", "leader_first", "text", "nethack.quest.val.leader_first.text", "\"Ah, %p, my %S.  You have returned to %H\nat last.  We are in dire need of your aid, but I must determine if you\nare yet ready for such an undertaking.\n\n\"Let me read your fate...\"", 0, nh_quest_bindings_855, 3},
    {"Val", "leader_last", "synopsis", "nethack.quest.val.leader_last.synopsis", "[\"Begone from my presence and never return.\"]", 0, NULL, 0},
    {"Val", "leader_last", "text", "nethack.quest.val.leader_last.text", "\"No, %p.  Your fate is sealed.  I must cast about for another\nchampion.  Begone from my presence, and never return.  Know this, that\nyou shall never succeed in this life, and Valhalla is denied to you.\"", 0, nh_quest_bindings_857, 1},
    {"Val", "leader_next", "text", "nethack.quest.val.leader_next.text", "\"Let me read the future for you now, %p, perhaps you have managed to\nchange it enough...\"", 0, nh_quest_bindings_858, 1},
    {"Val", "leader_other", "text", "nethack.quest.val.leader_other.text", "\"Again, I shall read your fate, my %S.  Let us both hope that you have\nmade changes to become ready for this task...\"", 0, nh_quest_bindings_859, 1},
    {"Val", "locate_first", "synopsis", "nethack.quest.val.locate_first.synopsis", "[This is the entrance to %i.]", 0, nh_quest_bindings_860, 1},
    {"Val", "locate_first", "text", "nethack.quest.val.locate_first.text", "The ice and snow gives way to a valley floor.  You %x ahead of you\na huge round hill surrounded by pools of lava.  This then is the entrance\nto %i.  It looks like you're not going to get in without\na fight though.", 0, nh_quest_bindings_861, 2},
    {"Val", "locate_next", "text", "nethack.quest.val.locate_next.text", "Once again, you stand before the entrance to %i.", 0, nh_quest_bindings_862, 1},
    {"Val", "nemesis_first", "synopsis", "nethack.quest.val.nemesis_first.synopsis", "[\"%oC has shown me that I must kill you.\"]", 0, nh_quest_bindings_863, 2},
    {"Val", "nemesis_first", "text", "nethack.quest.val.nemesis_first.text", "\"So!  %lC has finally sent %ca to challenge me!\n\n\"I thought that mastering %o would enable me to challenge\n%d, but it has shown me that first I must kill you!  So come, little\n%s.  Once I defeat you, I can at last begin the final battle with %d.\"", 0, nh_quest_bindings_864, 7},
    {"Val", "nemesis_next", "text", "nethack.quest.val.nemesis_next.text", "\"Again you challenge me, %r.  Good.  I will kill you now.\"", 0, nh_quest_bindings_865, 1},
    {"Val", "nemesis_other", "text", "nethack.quest.val.nemesis_other.text", "\"Have you not learned yet?  You cannot defeat %n!\"", 0, nh_quest_bindings_866, 1},
    {"Val", "nemesis_wantsit", "text", "nethack.quest.val.nemesis_wantsit.text", "\"I will kill you, %c, and wrest %o from your mangled hands.\"", 0, nh_quest_bindings_867, 2},
    {"Val", "nexttime", "text", "nethack.quest.val.nexttime.text", "Once again, you are near the abode of %l.", 0, nh_quest_bindings_868, 1},
    {"Val", "offeredit", "synopsis", "nethack.quest.val.offeredit.synopsis", "[Take %o.  Search for the Amulet.]", 0, nh_quest_bindings_869, 1},
    {"Val", "offeredit", "text", "nethack.quest.val.offeredit.text", "As you approach, %l rises and touches %o.\n\n\"You may take %o with you, %p.  I have removed from\nit the power to foretell the future, for that power no mortal should\nhave.  Its other abilities, however, you have at your disposal.\n\n\"You must now begin in %ds name to search for the Amulet of Yendor.\nMay your steps be guided by %d, my %S.\"", 0, nh_quest_bindings_870, 6},
    {"Val", "offeredit2", "synopsis", "nethack.quest.val.offeredit2.synopsis", "[You are %os keeper now.  Return through the portal and find the Amulet.]", 0, nh_quest_bindings_871, 2},
    {"Val", "offeredit2", "text", "nethack.quest.val.offeredit2.text", "\"Careful, %p!  %oC might break, and that would be\na tragic loss.  You are its keeper now, and the time has come to\nresume your search for the Amulet.  %Z await your\nreturn through the magic portal that brought you here.\"", 0, nh_quest_bindings_872, 4},
    {"Val", "othertime", "text", "nethack.quest.val.othertime.text", "Again you materialize near %ls abode.  You have a nagging feeling\nthat this may be the last time you come here.", 0, nh_quest_bindings_873, 2},
    {"Val", "posthanks", "text", "nethack.quest.val.posthanks.text", "\"Greetings, %p.  I have not been able to pay as much attention to\nyour search for the Amulet as I have wished.  How do you fare?\"", 0, nh_quest_bindings_874, 1},
    {"Wiz", "assignquest", "synopsis", "nethack.quest.wiz.assignquest.synopsis", "[Travel to %i; overcome %n; return with %o.]", 0, nh_quest_bindings_875, 3},
    {"Wiz", "assignquest", "text", "nethack.quest.wiz.assignquest.text", "\"Yes, %p, you truly are ready for this dire task.  Listen,\ncarefully, for what I tell you now will be of vital importance.\n\n\"Since you left us to hone your skills in the world, we unexpectedly came\nunder attack by the forces of %n.  As you know, we thought\n%n had perished at the end of the last age, but, alas, this was\nnot the case.\n\n\"%nC sent an army of abominations against us.  Among them was a\nminion, mindless and ensorcelled, and thus, in the confusion, it was\nable to penetrate our defenses.  Alas, this creature has stolen\n%o and I fear has delivered %oh to %n.\n\n\"Over the years, I had woven most of my power into this amulet, and thus,\nwithout it, I have but a shadow of my former power, and I fear that I\nshall soon perish.\n\n\"You must travel to %i, and within its dungeons,\nfind and overcome %n, and return %o to me.\n\n\"Go now, with %d, and complete this quest before it is too late.\"", 0, nh_quest_bindings_876, 7},
    {"Wiz", "badalign", "synopsis", "nethack.quest.wiz.badalign.synopsis", "[Go; come back when you are worthy of %d.]", 0, nh_quest_bindings_877, 1},
    {"Wiz", "badalign", "text", "nethack.quest.wiz.badalign.text", "\"You amaze me, %p!  How many times did I tell you that the way of a mage\nis an exacting one.  One must use the world with care, lest one leave it\nin ruins and simplify the task of %n.\n\n\"You must go back and show your worthiness.  Do not return until you are\ntruly ready for this quest.  May %d guide you in this task.\"", 0, nh_quest_bindings_878, 3},
    {"Wiz", "badlevel", "synopsis", "nethack.quest.wiz.badlevel.synopsis", "[Go; return when you are %Ra.]", 0, nh_quest_bindings_879, 2},
    {"Wiz", "badlevel", "text", "nethack.quest.wiz.badlevel.text", "\"Alas, %p, you have not yet shown your proficiency as a worthy\nspellcaster.  As %ra, you would surely be overcome in the challenge\nahead.  Go, now, expand your horizons, and return when you have attained\nrenown as %Ra.\"", 0, nh_quest_bindings_880, 3},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_1", "\"Your puny powers are no match for me, fool!\"", 1, NULL, 0},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_10", "\"Feel my power, %c!  My victory is imminent!\"", 10, nh_quest_bindings_882, 1},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_2", "\"When you are defeated, your torment will last for a thousand years.\"", 2, NULL, 0},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_3", "\"After your downfall, %p, I shall devour %l for dessert!\"", 3, nh_quest_bindings_884, 2},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_4", "\"Are you ready yet to beg for mercy?  I could be lenient...\"", 4, NULL, 0},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_5", "\"Your soul shall join the enslaved multitude I command!\"", 5, NULL, 0},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_6", "\"Your lack of will is evident, and you shall die as a result.\"", 6, NULL, 0},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_7", "\"Your faith in %d is for naught!  Come, submit to me now!\"", 7, nh_quest_bindings_888, 1},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_8", "\"A mere %r is nothing compared to my skill!\"", 8, nh_quest_bindings_889, 1},
    {"Wiz", "discourage", "item", "nethack.quest.wiz.discourage.item_9", "\"So, you are the best hope of %l?  How droll.\"", 9, nh_quest_bindings_890, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_1", "\"Beware, for %n is immune to most magical attacks.\"", 1, nh_quest_bindings_891, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_10", "\"You will know when %o is near.  Proceed with care!\"", 10, nh_quest_bindings_892, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_2", "\"To enter %i you must pass many traps.\"", 2, nh_quest_bindings_893, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_3", "\"%nC may be vulnerable to physical attacks.\"", 3, nh_quest_bindings_894, 2},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_4", "\"%d will come to your aid when you call.\"", 4, nh_quest_bindings_895, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_5", "\"You must utterly destroy %n.  He will pursue you otherwise.\"", 5, nh_quest_bindings_896, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_6", "\"%oC is a mighty artifact.  With it you can destroy %n.\"", 6, nh_quest_bindings_897, 2},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_7", "\"Go forth with the blessings of %d.\"", 7, nh_quest_bindings_898, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_8", "\"I will have my %gP watch for your return.\"", 8, nh_quest_bindings_899, 1},
    {"Wiz", "encourage", "item", "nethack.quest.wiz.encourage.item_9", "\"Feel free to take any items in that chest that might aid you.\"", 9, NULL, 0},
    {"Wiz", "firsttime", "synopsis", "nethack.quest.wiz.firsttime.synopsis", "[You have arrived at %ls tower but something is very wrong.]", 0, nh_quest_bindings_901, 2},
    {"Wiz", "firsttime", "text", "nethack.quest.wiz.firsttime.text", "You are suddenly in familiar surroundings.  You notice what appears to\nbe a large, squat stone structure nearby.  Wait!  That looks like the\ntower of your former teacher, %l.\n\nHowever, things are not the same as when you were last here.  Mists and\nareas of unexplained darkness surround the tower.  There is movement in\nthe shadows.\n\nYour teacher would never allow such unaesthetic forms to surround the\ntower...  unless something were dreadfully wrong!", 0, nh_quest_bindings_902, 1},
    {"Wiz", "goal_alt", "text", "nethack.quest.wiz.goal_alt.text", "You have returned to %ns lair.", 0, nh_quest_bindings_903, 1},
    {"Wiz", "goal_first", "text", "nethack.quest.wiz.goal_first.text", "You feel your mentor's presence; perhaps %o is nearby.", 0, nh_quest_bindings_904, 1},
    {"Wiz", "goal_next", "text", "nethack.quest.wiz.goal_next.text", "The aura of %o tingles at the edge of your perception.", 0, nh_quest_bindings_905, 1},
    {"Wiz", "gotit", "synopsis", "nethack.quest.wiz.gotit.synopsis", "[You feel %os power and know you should return %oh to %l.]", 0, nh_quest_bindings_906, 4},
    {"Wiz", "gotit", "text", "nethack.quest.wiz.gotit.text", "As you touch %o, its comforting power infuses you\nwith new energy.  You feel as if you can detect others' thoughts flowing\nthrough it.  Although you yearn to wear %o and\nattack the Wizard of Yendor, you know you must return it to its rightful\nowner, %l.", 0, nh_quest_bindings_907, 2},
    {"Wiz", "guardtalk_after", "item", "nethack.quest.wiz.guardtalk_after.item_1", "\"I have some eye of newt to trade, do you have a spare blind-worm's sting?\"", 1, NULL, 0},
    {"Wiz", "guardtalk_after", "item", "nethack.quest.wiz.guardtalk_after.item_2", "\"The magic portal now seems like it will remain stable for quite some time.\"", 2, NULL, 0},
    {"Wiz", "guardtalk_after", "item", "nethack.quest.wiz.guardtalk_after.item_3", "\"Have you noticed how much stronger %l is since %o was recovered?\"", 3, nh_quest_bindings_910, 2},
    {"Wiz", "guardtalk_after", "item", "nethack.quest.wiz.guardtalk_after.item_4", "\"Thank %d!  We weren't positive you would defeat %n.\"", 4, nh_quest_bindings_911, 2},
    {"Wiz", "guardtalk_after", "item", "nethack.quest.wiz.guardtalk_after.item_5", "\"I, too, will venture into the world, because %n was but one of many evils to be vanquished.\"", 5, nh_quest_bindings_912, 1},
    {"Wiz", "guardtalk_before", "item", "nethack.quest.wiz.guardtalk_before.item_1", "\"Would you happen to have some eye of newt in that overstuffed pack, %s?\"", 1, nh_quest_bindings_913, 1},
    {"Wiz", "guardtalk_before", "item", "nethack.quest.wiz.guardtalk_before.item_2", "\"Ah, the spell to create the magic portal worked.  Outstanding!\"", 2, NULL, 0},
    {"Wiz", "guardtalk_before", "item", "nethack.quest.wiz.guardtalk_before.item_3", "\"Hurry!  %lC may not survive that casting of the portal spell!\"", 3, nh_quest_bindings_915, 2},
    {"Wiz", "guardtalk_before", "item", "nethack.quest.wiz.guardtalk_before.item_4", "\"The spells of %n were just too powerful for us to withstand.\"", 4, nh_quest_bindings_916, 1},
    {"Wiz", "guardtalk_before", "item", "nethack.quest.wiz.guardtalk_before.item_5", "\"I, too, will venture into the world, because %n is but one of many evils to be vanquished.\"", 5, nh_quest_bindings_917, 1},
    {"Wiz", "hasamulet", "synopsis", "nethack.quest.wiz.hasamulet.synopsis", "[Take the Amulet to %ds altar on the Astral Plane.]", 0, nh_quest_bindings_918, 2},
    {"Wiz", "hasamulet", "text", "nethack.quest.wiz.hasamulet.text", "\"Congratulations, %p.  I always knew that if anyone could succeed\nin defeating the Wizard of Yendor and his minions, it would be you.\n\n\"Go now, and take the Amulet to the Astral Plane.  Once there, present\nthe Amulet on the altar of %d.  Along the way you shall pass through\nthe four Elemental Planes.  These planes are like nothing you have ever\nexperienced before, so be prepared!\n\n\"For this you were born, %s!  I am very proud of you.\"", 0, nh_quest_bindings_919, 3},
    {"Wiz", "killed_nemesis", "synopsis", "nethack.quest.wiz.killed_nemesis.synopsis", "[%nC curses you as %nh dies.]", 0, nh_quest_bindings_920, 3},
    {"Wiz", "killed_nemesis", "text", "nethack.quest.wiz.killed_nemesis.text", "%nC, whose body begins to shrivel up, croaks out:\n\n    \"I shall haunt your progress until the end of time.  A thousand\n    curses on you and %l.\"\n\nThen, the body bursts into a cloud of choking dust, and blows away.", 0, nh_quest_bindings_921, 3},
    {"Wiz", "leader_first", "synopsis", "nethack.quest.wiz.leader_first.synopsis", "[You have come a long way, but are you ready for the task I require?]", 0, NULL, 0},
    {"Wiz", "leader_first", "text", "nethack.quest.wiz.leader_first.text", "\"Come closer, %p, for my voice falters in my old age.\nYes, I see that you have come a long way since you went out into the\nworld, leaving the safe confines of this tower.  However, I must first\ndetermine if you have all of the skills required to take on the task\nI require of you.\"", 0, nh_quest_bindings_923, 1},
    {"Wiz", "leader_last", "synopsis", "nethack.quest.wiz.leader_last.synopsis", "[\"Get out of here!\"]", 0, NULL, 0},
    {"Wiz", "leader_last", "text", "nethack.quest.wiz.leader_last.text", "\"You fool, %p!  Why did I waste all of those years teaching you\nthe esoteric arts?  Get out of here!  I shall find another.\"", 0, nh_quest_bindings_925, 1},
    {"Wiz", "leader_next", "text", "nethack.quest.wiz.leader_next.text", "\"Well, %p, you have returned.  Perhaps you are now ready...\"", 0, nh_quest_bindings_926, 1},
    {"Wiz", "leader_other", "text", "nethack.quest.wiz.leader_other.text", "\"This is getting tedious, %p, but perseverance is a sign of a true mage.\nI certainly hope that you are truly ready this time!\"", 0, nh_quest_bindings_927, 1},
    {"Wiz", "locate_first", "text", "nethack.quest.wiz.locate_first.text", "Wisps of fog swirl nearby.  You feel that %ns lair is close.", 0, nh_quest_bindings_928, 2},
    {"Wiz", "locate_next", "text", "nethack.quest.wiz.locate_next.text", "You believe that you may once again invade %i.", 0, nh_quest_bindings_929, 1},
    {"Wiz", "nemesis_first", "synopsis", "nethack.quest.wiz.nemesis_first.synopsis", "[\"Your destruction should make for good sport.\"]", 0, NULL, 0},
    {"Wiz", "nemesis_first", "text", "nethack.quest.wiz.nemesis_first.text", "\"Ah, I recognize you, %p.  So, %l has sent you to steal\n%o from me, hmmm?  Well, %lh is a fool to send such\na mental weakling against me.\n\n\"Your destruction, however, should make for good sport.  In the end, you\nshall beg me to kill you!\"", 0, nh_quest_bindings_931, 4},
    {"Wiz", "nemesis_next", "synopsis", "nethack.quest.wiz.nemesis_next.synopsis", "[\"Your soul shall soon be mine to command.\"]", 0, NULL, 0},
    {"Wiz", "nemesis_next", "text", "nethack.quest.wiz.nemesis_next.text", "\"How nice of you to return, %p!  I enjoyed our last meeting.  Are you\nstill hungry for more pain?\n\n\"Come!  Your soul, like %o, shall soon be mine to command.\"", 0, nh_quest_bindings_933, 2},
    {"Wiz", "nemesis_other", "text", "nethack.quest.wiz.nemesis_other.text", "\"I'm sure that your perseverance shall be the subject of innumerable\nballads, but you shall not be around to hear them, I fear!\"", 0, NULL, 0},
    {"Wiz", "nemesis_wantsit", "text", "nethack.quest.wiz.nemesis_wantsit.text", "\"Thief!  %oC belongs to me, now.  I shall feed\nyour living flesh to my minions.\"", 0, nh_quest_bindings_935, 2},
    {"Wiz", "nexttime", "text", "nethack.quest.wiz.nexttime.text", "Once again, you are back at %H.", 0, nh_quest_bindings_936, 1},
    {"Wiz", "offeredit", "synopsis", "nethack.quest.wiz.offeredit.synopsis", "[Take %o with you in your quest for the Amulet.]", 0, nh_quest_bindings_937, 1},
    {"Wiz", "offeredit", "text", "nethack.quest.wiz.offeredit.text", "%lC notices %o in your possession,\nbeams at you and says:\n\n    \"I knew you could defeat %n and retrieve\n    %o.  We shall never forget this\n    brave service.\n\n    \"Take %oh with you in your quest for the Amulet of Yendor.\n    I can sense that it has attuned %oiself to you already.\n\n    \"May %d guide you in your quest, and keep you from harm.\"", 0, nh_quest_bindings_938, 7},
    {"Wiz", "offeredit2", "synopsis", "nethack.quest.wiz.offeredit2.synopsis", "[Keep %o, return through the portal to %Z; find the other Amulet.]", 0, nh_quest_bindings_939, 2},
    {"Wiz", "offeredit2", "text", "nethack.quest.wiz.offeredit2.text", "\"You are the keeper of %o now.  It is time to\nrecover the /other/ Amulet.  %Z await your return through\nthe magic portal which brought you here.\"", 0, nh_quest_bindings_940, 2},
    {"Wiz", "othertime", "text", "nethack.quest.wiz.othertime.text", "You are back at %H.\nYou have an odd feeling this may be the last time you ever come here.", 0, nh_quest_bindings_941, 1},
    {"Wiz", "posthanks", "text", "nethack.quest.wiz.posthanks.text", "\"Come near, my %S, and share your adventures with me.\nSo, have you succeeded in your quest for the Amulet of Yendor?\"", 0, nh_quest_bindings_942, 1},
};
